INSERT INTO pulse_platform_payload VALUES ($domain1_platform_v2${"schemaVersion":1,"contentVersion":"domain1.platform-draft.v2","sourceSha256":"ebe2591c8091f4a9277e678f2e4930aac2091ef4ff757e897edda28694fe84f9","courses":[{"code":"A1-F","title":"Tìm kiếm và lưu trữ thông tin cơ bản","outcome":"Tìm đúng nguồn, kiểm tra dấu hiệu tin cậy và lưu lại tài liệu để người khác truy xuất được.","final":{"title":"Bài cuối khóa M1-F · vị trí của bạn","promptHtml":"<h3>Tình huống</h3><p>Áp dụng vào một quyết định thực tế của vị trí.</p><h3>Yêu cầu</h3><p>Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.</p><h3>Các bước cần thực hiện</h3><ul><li>Nêu nhu cầu và từ khóa; tìm 3 nguồn, ghi tác giả hoặc đơn vị, kỳ và lý do tin cậy của từng nguồn.</li><li>Lưu ít nhất 1 tệp vào thư mục có tên và phiên bản; nộp ảnh hoặc sơ đồ thư mục.</li><li>Viết 5 ý tóm tắt, mỗi ý ghi nguồn; bản tổng hợp tối đa 1 trang, kèm minh chứng thư mục.</li></ul><h3>Sản phẩm cần nộp</h3><ul><li>Nhật ký nguồn và định nghĩa</li><li>Sản phẩm công việc có thể kiểm tra</li><li>Giới hạn và đề xuất tiếp theo</li></ul>","criteria":["Từ khóa hợp lý, không chép nguyên câu hỏi","3 nguồn có đánh giá độ tin cậy","Tệp lưu đúng thư mục và tên quy ước","5 ý tóm tắt có nguồn cho từng ý","Trình bày rõ, đúng hạn"]},"modules":[{"title":"Tìm kiếm thông tin bằng từ khóa","quizTitle":"Ôn tập · Tìm kiếm thông tin bằng từ khóa","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S01\"><p><strong>01 / Xác định</strong></p><h3>Biết mình cần tìm gì</h3><p>Trước khi mở trình tìm kiếm, ghi rõ câu hỏi công việc, phạm vi, thời điểm cần số liệu và người sẽ dùng kết quả. Câu “cần thông tin thị trường” quá rộng; “số đơn hàng tháng 9 của kênh trực tuyến” có thể kiểm tra được.</p><aside><h4>Từ nhu cầu đến truy vấn</h4><ul><li>01 · Câu hỏi · Cần thông tin gì?</li><li>02 · Phạm vi · Đối tượng · kỳ · đơn vị</li><li>03 · Nguồn · Đường dẫn gốc</li></ul><p>Ba ô nối tiếp mô tả cách chuyển một yêu cầu công việc thành truy vấn có thể lặp lại.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một câu nhu cầu thông tin có phạm vi và kỳ thời gian.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba ô nối tiếp mô tả cách chuyển một yêu cầu công việc thành truy vấn có thể lặp lại.","altText":"Ba ô nối tiếp mô tả cách chuyển một yêu cầu công việc thành truy vấn có thể lặp lại."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S02\"><p><strong>02 / Tìm kiếm</strong></p><h3>Từ khóa thay cho câu hỏi dài</h3><p>Công cụ tìm kiếm tra trong chỉ mục trang đã thu thập, không quét toàn bộ Internet ngay khi bạn gõ. Chọn 2–4 từ mang nghĩa chính: đối tượng, chỉ tiêu và thời điểm. Đọc tiêu đề, địa chỉ và mô tả của kết quả trước khi mở. Nhãn “Được tài trợ” nói về vị trí quảng cáo, không bảo đảm nội dung chính xác. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Hai truy vấn cùng một nhu cầu</h4><ul><li>Rộng · doanh thu · Quá nhiều kết quả</li><li>Rõ hơn · doanh thu trực tuyến 09/2026 · Có phạm vi và kỳ</li></ul><p>Minh họa truy vấn mơ hồ và truy vấn được thu hẹp bằng đối tượng, chỉ tiêu, thời gian.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi hai truy vấn: truy vấn đầu và truy vấn đã tinh chỉnh.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Minh họa truy vấn mơ hồ và truy vấn được thu hẹp bằng đối tượng, chỉ tiêu, thời gian.","altText":"Minh họa truy vấn mơ hồ và truy vấn được thu hẹp bằng đối tượng, chỉ tiêu, thời gian."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S03\"><p><strong>03 / Truy vết</strong></p><h3>Đến tài liệu gốc</h3><p>Đối chiếu trang tóm tắt với tài liệu do đơn vị tạo ra thông tin công bố. Ghi đường dẫn, tác giả hoặc đơn vị và ngày truy cập. Nếu không thấy tài liệu gốc, hãy ghi rõ giới hạn thay vì tự đoán.</p><aside><h4>Dấu vết nguồn</h4><ul><li>Kết quả tìm · Trang tóm tắt</li><li>Tài liệu gốc · Đơn vị tạo dữ liệu</li><li>Nhật ký · URL · ngày truy cập</li></ul><p>Sơ đồ lần ngược từ kết quả tìm kiếm về tài liệu gốc và nhật ký nguồn.</p></aside><section><h4>Tự kiểm tra</h4><p>Lưu nguồn gốc cùng nhật ký tìm kiếm.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Sơ đồ lần ngược từ kết quả tìm kiếm về tài liệu gốc và nhật ký nguồn.","altText":"Sơ đồ lần ngược từ kết quả tìm kiếm về tài liệu gốc và nhật ký nguồn."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S04\"><p><strong>04 / Tách yêu cầu</strong></p><h3>Biến lời nhờ mơ hồ thành câu hỏi tìm</h3><p>Khi ai đó yêu cầu “tìm số liệu mới nhất”, hãy hỏi số liệu nào, cho đơn vị nào, kỳ nào và dùng để làm gì. Câu trả lời quyết định từ khóa cũng như nguồn có thẩm quyền. Nếu thiếu một trong các yếu tố này, hãy ghi giả định trước khi tìm.</p><aside><h4>Hai yêu cầu</h4><ul><li>Mơ hồ · Tìm doanh thu mới nhất</li><li>Có thể làm · Doanh thu online · 09/2026 · chi nhánh A</li></ul><p>So sánh lời nhờ mơ hồ với câu hỏi công việc có phạm vi kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết lại yêu cầu thành một câu có đối tượng, chỉ tiêu và kỳ.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"So sánh lời nhờ mơ hồ với câu hỏi công việc có phạm vi kiểm tra được.","altText":"So sánh lời nhờ mơ hồ với câu hỏi công việc có phạm vi kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S05\"><p><strong>05 / Chọn từ khóa</strong></p><h3>Tạo nhóm từ khóa rồi tinh chỉnh</h3><p>Bắt đầu với danh từ chỉ đối tượng và chỉ tiêu, sau đó thêm thời gian hoặc mã nội bộ. Nếu kết quả quá rộng, thu hẹp phạm vi; nếu không có kết quả, thử tên đồng nghĩa hoặc bỏ bớt điều kiện. Lưu cả truy vấn đầu và truy vấn đã sửa để người khác lặp lại.</p><aside><h4>Vòng tinh chỉnh</h4><ul><li>1 · Tìm rộng · Chủ đề chính</li><li>2 · Đọc kết quả · Xem lệch ở đâu</li><li>3 · Tinh chỉnh · Thêm kỳ · mã · nguồn</li></ul><p>Ba bước phản hồi cho thấy truy vấn được điều chỉnh dựa trên kết quả, không tìm tùy tiện.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu lý do đổi một từ khóa trong truy vấn.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba bước phản hồi cho thấy truy vấn được điều chỉnh dựa trên kết quả, không tìm tùy tiện.","altText":"Ba bước phản hồi cho thấy truy vấn được điều chỉnh dựa trên kết quả, không tìm tùy tiện."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S06\"><p><strong>06 / Đọc kết quả</strong></p><h3>Không chọn nguồn vì đứng đầu danh sách</h3><p>Dòng kết quả tìm kiếm chỉ cho biết tiêu đề, địa chỉ và đoạn trích. Mở tài liệu để kiểm tra người công bố, kỳ số liệu và phương pháp. Kết quả quảng cáo hoặc bản sao có thể hữu ích để định hướng, nhưng không trở thành nguồn gốc chỉ vì xuất hiện trước.</p><aside><h4>Một kết quả cần kiểm tra</h4><ul><li>Tiêu đề · Báo cáo tháng 9</li><li>Địa chỉ · Nơi đăng chưa rõ</li><li>Cần mở · Tác giả · kỳ · tài liệu gốc</li></ul><p>Thẻ kết quả tìm kiếm minh họa thông tin hiện ra và thông tin phải kiểm tra tiếp.</p></aside><section><h4>Tự kiểm tra</h4><p>Chỉ ra ba dữ kiện cần xem sau khi mở kết quả.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Thẻ kết quả tìm kiếm minh họa thông tin hiện ra và thông tin phải kiểm tra tiếp.","altText":"Thẻ kết quả tìm kiếm minh họa thông tin hiện ra và thông tin phải kiểm tra tiếp."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Tìm đúng hồ sơ của công việc mình</h3><p>Áp dụng cách tìm vào bộ dữ liệu của vị trí đang học. Ghi rõ mã, kỳ và nơi giữ tài liệu gốc; nếu chỉ có bản chụp hoặc bản chưa duyệt, hãy đánh dấu cần xác minh. Cùng một kỹ năng tìm kiếm sẽ cho câu hỏi và nguồn khác nhau ở Kế toán và Marketing. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu nguồn đầu tiên sẽ mở và lý do.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Nộp nhật ký tìm ngắn gọn</h3><p>Trước khi sang mô đun sau, hãy lưu câu hỏi ban đầu, hai truy vấn, nguồn cuối cùng và một nguồn đã loại cùng lý do. Một đồng nghiệp phải có thể lặp lại đường tìm mà không hỏi lại bạn. Đây là bước chuẩn bị trực tiếp cho bài cuối khóa.</p><aside><h4>Sản phẩm của mô đun</h4><ul><li>01 · Câu hỏi · Nêu phạm vi</li><li>02 · Nhật ký · Hai truy vấn</li><li>03 · Nguồn · URL · lý do chọn</li></ul><p>Ba thành phần của nhật ký tìm là câu hỏi, truy vấn và nguồn được chọn có lý do.</p></aside><section><h4>Tự kiểm tra</h4><p>Kiểm tra xem người khác có mở lại nguồn gốc từ nhật ký không.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba thành phần của nhật ký tìm là câu hỏi, truy vấn và nguồn được chọn có lý do.","altText":"Ba thành phần của nhật ký tìm là câu hỏi, truy vấn và nguồn được chọn có lý do."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Lập nhật ký tìm và truy nguồn</h3><p>Yêu cầu “tìm số liệu tháng 9” chưa đủ để tìm. Viết lại thành “số đơn hàng trực tuyến của chiến dịch CAMP07 trong 01–30/09/2026 để so với báo cáo bán hàng”. Truy vấn đầu “đơn hàng CAMP07” còn rộng; truy vấn sau thêm kỳ và hệ thống nguồn. Nhật ký ghi cả hai truy vấn, đường dẫn báo cáo gốc, người xuất và thời điểm truy cập. Nếu chỉ thấy ảnh chụp, ghi trạng thái “chưa xác minh”, không tự tạo số. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Lập nhật ký tìm và truy nguồn</h3><p>Từ một yêu cầu mơ hồ, tạo truy vấn có phạm vi và dẫn được người khác tới nguồn gốc. Thực hiện theo bốn bước: 1) Viết câu hỏi công việc gồm đối tượng, chỉ tiêu, kỳ và mục đích. 2) Tìm tối đa ba lượt; ghi từ khóa ở mỗi lượt và vì sao đổi từ khóa. 3) Mở tài liệu gốc, ghi đơn vị tạo dữ liệu, ngày/kỳ và URL hoặc mã hồ sơ. 4) Nêu một kết quả bị loại và lý do; bàn giao nhật ký để người khác lặp lại. Sản phẩm cần tạo: Nhật ký một trang: câu hỏi, tối đa ba lượt tìm, nguồn chọn, nguồn loại và giới hạn còn chưa xác minh.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Viết câu hỏi công việc gồm đối tượng, chỉ tiêu, kỳ và mục đích.</li><li>02 · Tìm tối đa ba lượt; ghi từ khóa ở mỗi lượt và vì sao đổi từ khóa.</li><li>03 · Mở tài liệu gốc, ghi đơn vị tạo dữ liệu, ngày/kỳ và URL hoặc mã hồ sơ.</li><li>04 · Nêu một kết quả bị loại và lý do; bàn giao nhật ký để người khác lặp lại.</li></ul><p>Quy trình thực hành lập nhật ký tìm và truy nguồn có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Quy trình thực hành lập nhật ký tìm và truy nguồn có sản phẩm kiểm tra được.","altText":"Quy trình thực hành lập nhật ký tìm và truy nguồn có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-F/M01/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Truy vấn thứ hai khác có chủ đích so với truy vấn đầu. Nguồn được chọn là nguồn gốc hoặc ghi rõ không tìm được nguồn gốc. Người nhận có thể tìm lại tài liệu mà không hỏi người lập. Lỗi thường gặp: Chọn kết quả đầu tiên hoặc ảnh chụp vì nhìn có vẻ đúng mà không giữ dấu vết nguồn. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Truy vấn thứ hai khác có chủ đích so với truy vấn đầu.</li><li>Tiêu chí 2 · Nguồn được chọn là nguồn gốc hoặc ghi rõ không tìm được nguồn gốc.</li><li>Tiêu chí 3 · Người nhận có thể tìm lại tài liệu mà không hỏi người lập.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Cách tìm nào có thể kiểm tra lại?","explanation":"Truy vấn và nguồn gốc cần được ghi để người khác lặp lại việc tìm.","options":[{"text":"Gõ câu hỏi rất dài rồi chọn kết quả đầu","isCorrect":false},{"text":"Ghi nhu cầu, dùng từ khóa chính và lưu đường dẫn nguồn","isCorrect":true},{"text":"Chỉ đọc kết quả có nhãn quảng cáo","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Yêu cầu nào đủ rõ để bắt đầu tìm?","explanation":"Cần có đối tượng, chỉ tiêu, kỳ và mục đích sử dụng.","options":[{"text":"Tìm mọi thứ về khách hàng","isCorrect":false},{"text":"Tìm số đơn hàng kênh trực tuyến của tháng 9/2026 để đối chiếu báo cáo","isCorrect":true},{"text":"Tìm kết quả mới nhất trên mạng","isCorrect":false}]},{"text":"Một kết quả được tài trợ xuất hiện đầu danh sách. Bạn làm gì?","explanation":"Vị trí quảng cáo không chứng minh nội dung đúng hoặc sai.","options":[{"text":"Dùng ngay vì đứng đầu","isCorrect":false},{"text":"Bỏ hết kết quả được tài trợ","isCorrect":false},{"text":"Mở và kiểm tra tác giả, nguồn gốc, kỳ dữ liệu như các kết quả khác","isCorrect":true}]},{"text":"Nhật ký tìm kiếm nào giúp đồng nghiệp lặp lại?","explanation":"Nhật ký phải giữ đường tìm và căn cứ chọn nguồn.","options":[{"text":"Chỉ ghi kết luận","isCorrect":false},{"text":"Ghi câu hỏi, hai truy vấn đã thử, URL nguồn và lý do chọn","isCorrect":true},{"text":"Chụp màn hình trang kết quả","isCorrect":false}]}]},{"title":"Nhận biết nguồn đáng tin cậy","quizTitle":"Ôn tập · Nhận biết nguồn đáng tin cậy","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S01\"><p><strong>01 / Nhận diện</strong></p><h3>Ai đứng sau thông tin?</h3><p>Xem tên tổ chức, tác giả, tài liệu gốc và cách liên hệ. Tên miền chỉ là tín hiệu để xác định nơi xuất bản, không phải bằng chứng tự động rằng số liệu đúng.</p><aside><h4>Hồ sơ một nguồn</h4><ul><li>Tác giả · Ai tạo ra số liệu?</li><li>Kỳ dữ liệu · Tháng nào, năm nào?</li><li>Mục đích · Báo cáo hay quảng cáo?</li></ul><p>Phiếu kiểm nguồn gồm tác giả, kỳ dữ liệu và mục đích công bố.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi người tạo dữ liệu và người đăng lại.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Phiếu kiểm nguồn gồm tác giả, kỳ dữ liệu và mục đích công bố.","altText":"Phiếu kiểm nguồn gồm tác giả, kỳ dữ liệu và mục đích công bố."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S02\"><p><strong>02 / Kiểm tra</strong></p><h3>Thông tin có còn phù hợp?</h3><p>Kiểm tra ngày công bố, kỳ dữ liệu, phương pháp và mục đích của bài viết. Một nguồn đáng tin ở chủ đề này có thể không phù hợp với câu hỏi khác. Bài không ghi nguồn hoặc chỉ giật tít cần được kiểm chứng thêm. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Mới chưa chắc phù hợp</h4><ul><li>Nguồn A · Xuất hôm nay · Dữ liệu năm trước</li><li>Nguồn B · Xuất tuần trước · Dữ liệu đúng kỳ cần</li></ul><p>Hai nguồn được so theo ngày xuất và kỳ dữ liệu, cho thấy ngày xuất mới không tự bảo đảm phù hợp.</p></aside><section><h4>Tự kiểm tra</h4><p>So thời điểm của nguồn với thời điểm quyết định.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Hai nguồn được so theo ngày xuất và kỳ dữ liệu, cho thấy ngày xuất mới không tự bảo đảm phù hợp.","altText":"Hai nguồn được so theo ngày xuất và kỳ dữ liệu, cho thấy ngày xuất mới không tự bảo đảm phù hợp."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S03\"><p><strong>03 / Đối chiếu</strong></p><h3>Hai trang chưa chắc là hai nguồn</h3><p>Nếu hai trang cùng trích một báo cáo, chúng không tạo thành hai bằng chứng độc lập. Mở liên kết về báo cáo gốc và ghi điểm trùng hoặc khác nhau trước khi kết luận.</p><aside><h4>Hai trang, một nguồn gốc</h4><ul><li>Trang A · Trích báo cáo X</li><li>Trang B · Trích báo cáo X</li><li>Nguồn gốc · Báo cáo X</li></ul><p>Hai trang dẫn cùng báo cáo X được gom về một nguồn gốc thay vì đếm thành hai bằng chứng độc lập.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu một điểm còn chưa xác minh được.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Hai trang dẫn cùng báo cáo X được gom về một nguồn gốc thay vì đếm thành hai bằng chứng độc lập.","altText":"Hai trang dẫn cùng báo cáo X được gom về một nguồn gốc thay vì đếm thành hai bằng chứng độc lập."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S04\"><p><strong>04 / Bằng chứng</strong></p><h3>Tách người đăng khỏi người tạo dữ liệu</h3><p>Một bài tổng hợp có thể dẫn nguồn đáng tin nhưng vẫn diễn giải sai. Hãy lần về báo cáo do đơn vị tạo dữ liệu công bố, xem bảng và phần phương pháp. Ghi rõ đâu là dữ liệu, đâu là nhận định của tác giả và đâu là suy luận của mình.</p><aside><h4>Chuỗi truyền thông tin</h4><ul><li>Đơn vị tạo · Bảng gốc</li><li>Người đăng · Bài tóm tắt</li><li>Người học · Kết luận có dẫn nguồn</li></ul><p>Ba lớp thể hiện số liệu có thể bị diễn giải qua từng lần đăng lại.</p></aside><section><h4>Tự kiểm tra</h4><p>Phân loại một câu trong tài liệu thành số liệu hay nhận định.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba lớp thể hiện số liệu có thể bị diễn giải qua từng lần đăng lại.","altText":"Ba lớp thể hiện số liệu có thể bị diễn giải qua từng lần đăng lại."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S05\"><p><strong>05 / Thời điểm</strong></p><h3>So ngày công bố với kỳ dữ liệu</h3><p>Bài xuất hôm nay có thể dùng số liệu từ năm trước. Mỗi nguồn cần hai mốc: ngày tài liệu được công bố hoặc cập nhật và kỳ mà số liệu thực sự phản ánh. Quyết định cần số hiện tại thì nguồn quá cũ phải ghi rõ hạn chế, dù tổ chức xuất bản rất uy tín.</p><aside><h4>Hai mốc khác nhau</h4><ul><li>09/2025 · Kỳ dữ liệu</li><li>10/2026 · Ngày xuất bài</li></ul><p>Trục thời gian cho thấy bài mới xuất nhưng dữ liệu bên trong cũ hơn một năm.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nguồn đúng kỳ và nguồn cần bổ sung.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Trục thời gian cho thấy bài mới xuất nhưng dữ liệu bên trong cũ hơn một năm.","altText":"Trục thời gian cho thấy bài mới xuất nhưng dữ liệu bên trong cũ hơn một năm."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S06\"><p><strong>06 / Độc lập</strong></p><h3>Hai đường link có thể cùng một bằng chứng</h3><p>Trước khi nói đã kiểm tra chéo, xem hai trang lấy số từ đâu. Nếu cả hai trích báo cáo X, số nguồn độc lập là một. Muốn kiểm chứng mạnh hơn, tìm nguồn có cách thu thập riêng hoặc kiểm tra trực tiếp sổ/hệ thống gốc.</p><aside><h4>Nguồn lặp không tăng độ chắc</h4><ul><li>Bài A · Dẫn X</li><li>Bài B · Dẫn X</li><li>Báo cáo X · Một nguồn gốc</li></ul><p>Hai bài A/B quy về cùng báo cáo X; sơ đồ không đếm thành hai xác nhận độc lập.</p></aside><section><h4>Tự kiểm tra</h4><p>Vẽ mũi tên từ từng trang tới nơi tạo số liệu.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Hai bài A/B quy về cùng báo cáo X; sơ đồ không đếm thành hai xác nhận độc lập.","altText":"Hai bài A/B quy về cùng báo cáo X; sơ đồ không đếm thành hai xác nhận độc lập."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Chấm độ tin cậy trước khi dùng</h3><p>Trong hồ sơ của vị trí, hãy so bản gốc, bản sao và bản chưa duyệt. Nguồn phù hợp phải đúng đối tượng, kỳ và trạng thái. Một ảnh chụp có thể giúp nhận ra vấn đề nhưng không thay thế tệp gốc có lịch sử/phiên bản. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn một nguồn chính và ghi một điều còn nghi vấn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Viết nhận xét nguồn không tuyệt đối hóa</h3><p>Ghi kết luận theo cấu trúc: nguồn này đủ dùng cho câu hỏi nào, vì sao và giới hạn ở đâu. Tránh gắn nhãn “đáng tin hoàn toàn” hoặc “sai hoàn toàn” nếu chưa kiểm tra phương pháp. Minh bạch giới hạn là một phần của năng lực đánh giá nguồn.</p><aside><h4>Ba phần nhận xét</h4><ul><li>Phù hợp · Đúng câu hỏi · kỳ</li><li>Căn cứ · Có gốc · phương pháp</li><li>Giới hạn · Điều chưa xác minh</li></ul><p>Khung nhận xét nguồn có phần dùng được, lý do và giới hạn chưa kiểm tra.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết hai câu đánh giá một nguồn, có điều kiện sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Khung nhận xét nguồn có phần dùng được, lý do và giới hạn chưa kiểm tra.","altText":"Khung nhận xét nguồn có phần dùng được, lý do và giới hạn chưa kiểm tra."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Chấm độ phù hợp của ba nguồn</h3><p>Có ba lựa chọn: báo cáo gốc đã duyệt của đúng kỳ; bài tóm tắt trích báo cáo đó; ảnh chụp bảng không ghi người xuất. Báo cáo gốc là nguồn chính. Bài tóm tắt hữu ích để định hướng nhưng không phải xác nhận độc lập. Ảnh chụp chỉ là dấu hiệu cần kiểm tra. Kết luận phải nêu báo cáo gốc phù hợp cho câu hỏi nào và điểm còn thiếu, ví dụ phương pháp chọn mẫu. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Chấm độ phù hợp của ba nguồn</h3><p>Xếp hạng năm nguồn theo nguồn gốc, kỳ dữ liệu, mục đích và khả năng kiểm chứng trước khi dùng. Thực hiện theo bốn bước: 1) Chọn năm kết quả cùng chủ đề; lập bảng tác giả/đơn vị tạo, ngày xuất, kỳ dữ liệu, phương pháp và mục đích. 2) Vẽ mũi tên từ bài tóm tắt và ảnh chụp về nguồn được trích, nếu có. 3) Xếp hạng năm nguồn; ghi nguồn nào chỉ dùng để định hướng và vì sao. 4) Viết hai câu kết luận: phạm vi sử dụng được và giới hạn cần xác minh. Sản phẩm cần tạo: Bảng xếp hạng năm nguồn, mỗi nguồn có một câu giải thích và quyết định dùng/chưa dùng.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Chọn năm kết quả cùng chủ đề; lập bảng tác giả/đơn vị tạo, ngày xuất, kỳ dữ liệu, phương pháp và mục đích.</li><li>02 · Vẽ mũi tên từ bài tóm tắt và ảnh chụp về nguồn được trích, nếu có.</li><li>03 · Xếp hạng năm nguồn; ghi nguồn nào chỉ dùng để định hướng và vì sao.</li><li>04 · Viết hai câu kết luận: phạm vi sử dụng được và giới hạn cần xác minh.</li></ul><p>Quy trình thực hành chấm độ phù hợp của ba nguồn có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Quy trình thực hành chấm độ phù hợp của ba nguồn có sản phẩm kiểm tra được.","altText":"Quy trình thực hành chấm độ phù hợp của ba nguồn có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-F/M02/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Không đếm hai trang cùng trích một báo cáo là hai nguồn độc lập. Phân biệt ngày đăng bài với kỳ số liệu. Không dùng nhãn “đáng tin tuyệt đối” khi phương pháp chưa rõ. Lỗi thường gặp: Coi nhiều đường link là nhiều xác nhận dù tất cả lấy từ một bảng gốc. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Không đếm hai trang cùng trích một báo cáo là hai nguồn độc lập.</li><li>Tiêu chí 2 · Phân biệt ngày đăng bài với kỳ số liệu.</li><li>Tiêu chí 3 · Không dùng nhãn “đáng tin tuyệt đối” khi phương pháp chưa rõ.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Khi hai bài cùng ghi một con số, bạn nên làm gì?","explanation":"Các trang cùng chép một báo cáo chỉ là một nguồn gốc dữ liệu.","options":[{"text":"Coi đó là hai xác nhận độc lập","isCorrect":false},{"text":"Chọn bài có nhiều lượt xem hơn","isCorrect":false},{"text":"Kiểm tra xem cả hai có cùng dẫn về một nguồn gốc không","isCorrect":true}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Bài viết đăng hôm nay nhưng số liệu thuộc năm trước. Nhận xét nào đúng?","explanation":"Ngày xuất bài và kỳ mà dữ liệu phản ánh là hai mốc khác nhau.","options":[{"text":"Luôn phù hợp vì mới đăng","isCorrect":false},{"text":"Cần đối chiếu kỳ dữ liệu với kỳ của quyết định","isCorrect":true},{"text":"Chỉ cần xem lượt chia sẻ","isCorrect":false}]},{"text":"Bài A và B đều trích báo cáo X. Có bao nhiêu nguồn gốc độc lập?","explanation":"Hai đường dẫn cùng quy về báo cáo X không tạo hai bằng chứng độc lập.","options":[{"text":"Một","isCorrect":true},{"text":"Hai","isCorrect":false},{"text":"Ba","isCorrect":false}]},{"text":"Nhận xét nào về một nguồn là minh bạch nhất?","explanation":"Đánh giá nguồn phải nói rõ phạm vi dùng được và giới hạn chưa xác minh.","options":[{"text":"Nguồn này chắc chắn đúng mọi trường hợp","isCorrect":false},{"text":"Nguồn này dùng được cho kỳ tháng 9, nhưng chưa rõ cách chọn mẫu","isCorrect":true},{"text":"Nguồn này có biểu đồ đẹp","isCorrect":false}]}]},{"title":"Lưu trữ và sắp xếp tài liệu","quizTitle":"Ôn tập · Lưu trữ và sắp xếp tài liệu","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S01\"><p><strong>01 / Định dạng</strong></p><h3>Chọn tệp đúng việc</h3><p>Bảng tính phù hợp khi cần tính và lọc; PDF phù hợp khi cần chia sẻ bố cục cố định. Luôn giữ tệp gốc và ghi nơi lấy. Đừng biến ảnh chụp thành “dữ liệu gốc” nếu vẫn còn bảng nguồn.</p><aside><h4>Tệp để xử lý và tệp để đọc</h4><ul><li>Bảng tính · Lọc · tính · kiểm tra</li><li>PDF · Đọc bản đã chốt</li></ul><p>Hai thẻ minh họa chọn định dạng theo mục đích xử lý tiếp hay chia sẻ bản cố định.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn định dạng phù hợp với việc xử lý tiếp theo.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Hai thẻ minh họa chọn định dạng theo mục đích xử lý tiếp hay chia sẻ bản cố định.","altText":"Hai thẻ minh họa chọn định dạng theo mục đích xử lý tiếp hay chia sẻ bản cố định."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S02\"><p><strong>02 / Tổ chức</strong></p><h3>Tên tệp mô tả được nội dung</h3><p>Dùng quy ước ổn định như năm-tháng-ngày_chủ-đề_phiên-bản. Đặt các thành phần ở cùng vị trí trong mọi tên tệp để sắp xếp và tìm lại. Tránh các tên “final2_moi_nhat”. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Quy ước tên tệp</h4><ul><li>Kỳ · 2026-09</li><li>Chủ đề · chung-tu_CP017</li><li>Phiên bản · v01.pdf</li></ul><p>Tên tệp được ghép từ kỳ, chủ đề và phiên bản để sắp xếp, tra cứu.</p></aside><section><h4>Tự kiểm tra</h4><p>Đề xuất một tên tệp và thư mục dễ tra cứu.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Tên tệp được ghép từ kỳ, chủ đề và phiên bản để sắp xếp, tra cứu.","altText":"Tên tệp được ghép từ kỳ, chủ đề và phiên bản để sắp xếp, tra cứu."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S03\"><p><strong>03 / Bàn giao</strong></p><h3>Giữ phiên bản và đường dẫn</h3><p>Sổ ghi nguồn nên có tên, đường dẫn, người phụ trách, kỳ dữ liệu và phiên bản. Tài liệu nhạy cảm chỉ chia sẻ với người cần dùng. Khi sửa, tạo phiên bản mới hoặc ghi lịch sử thay đổi thay vì ghi đè không dấu vết.</p><aside><h4>Chuỗi bàn giao</h4><ul><li>Nguồn gốc · Tệp gốc</li><li>Bản làm việc · Có phiên bản</li><li>Người nhận · Đúng quyền</li></ul><p>Sơ đồ lưu bản gốc, tạo bản làm việc có phiên bản và chia sẻ đúng quyền.</p></aside><section><h4>Tự kiểm tra</h4><p>Kiểm tra người nhận có quyền phù hợp.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Sơ đồ lưu bản gốc, tạo bản làm việc có phiên bản và chia sẻ đúng quyền.","altText":"Sơ đồ lưu bản gốc, tạo bản làm việc có phiên bản và chia sẻ đúng quyền."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S04\"><p><strong>04 / Cây thư mục</strong></p><h3>Sắp theo một quy tắc mà cả nhóm hiểu</h3><p>Chọn một trục chính như kỳ công việc hoặc dự án; bên dưới mới tách nguồn, bản làm việc và bản duyệt. Nếu một tệp hợp với hai thư mục, hãy dùng sổ đăng ký hoặc liên kết thay vì tạo hai bản không đồng bộ. Tên thư mục cần ngắn nhưng đủ phân biệt.</p><aside><h4>Thư mục mẫu</h4><ul><li>2026-09 · Kỳ</li><li>01_Nguồn · Tệp gốc</li><li>02_Làm-việc · Bản đang sửa</li><li>03_Duyệt · Bản chốt</li></ul><p>Cây thư mục minh họa một kỳ và ba trạng thái tài liệu thay vì nhiều bản rải rác.</p></aside><section><h4>Tự kiểm tra</h4><p>Vẽ cây ba tầng cho ca học của bạn.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Cây thư mục minh họa một kỳ và ba trạng thái tài liệu thay vì nhiều bản rải rác.","altText":"Cây thư mục minh họa một kỳ và ba trạng thái tài liệu thay vì nhiều bản rải rác."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S05\"><p><strong>05 / Phiên bản</strong></p><h3>Đừng dùng tên “final_final”</h3><p>Phiên bản nên tăng có quy tắc: v01 là bản đầu, v02 là bản sửa; ngày hoặc kỳ đứng đầu giúp sắp xếp. Giữ ghi chú ngắn về thay đổi quan trọng. Nếu tài liệu được duyệt lại, trạng thái duyệt là trường riêng, không chỉ suy từ tên tệp.</p><aside><h4>Hai bản có dấu vết</h4><ul><li>v01 · Bản nhận</li><li>v02 · Sửa số liệu</li><li>Duyệt · Có trạng thái riêng</li></ul><p>Trục phiên bản phân biệt số phiên bản với trạng thái phê duyệt.</p></aside><section><h4>Tự kiểm tra</h4><p>Đặt tên cho bản gốc và bản sửa của cùng tài liệu.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Trục phiên bản phân biệt số phiên bản với trạng thái phê duyệt.","altText":"Trục phiên bản phân biệt số phiên bản với trạng thái phê duyệt."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S06\"><p><strong>06 / Quyền xem</strong></p><h3>Chia sẻ theo nhiệm vụ</h3><p>Trước khi gửi liên kết, hỏi người nhận cần xem hay sửa, trong bao lâu và có dữ liệu cá nhân không. Chia sẻ tệp đã duyệt để đọc nếu chỉ cần tham khảo; giữ thư mục nguồn và bản làm việc cho người có trách nhiệm. Không đưa tệp nhạy cảm vào kho công khai.</p><aside><h4>Quyền tương ứng việc</h4><ul><li>Người kiểm tra · Xem bản chốt</li><li>Người soạn · Sửa bản làm việc</li><li>Công khai · Không chứa dữ liệu nhạy cảm</li></ul><p>Ba ví dụ gắn quyền với nhu cầu, theo nguyên tắc quyền tối thiểu.</p></aside><section><h4>Tự kiểm tra</h4><p>Chỉ định quyền xem/sửa cho hai người nhận khác nhau.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Ba ví dụ gắn quyền với nhu cầu, theo nguyên tắc quyền tối thiểu.","altText":"Ba ví dụ gắn quyền với nhu cầu, theo nguyên tắc quyền tối thiểu."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Bàn giao một bộ hồ sơ tìm được</h3><p>Tạo sổ ghi tên, mã, kỳ, nguồn và phiên bản cho các tệp trong ca học. Kiểm tra bản nào đã duyệt và bản nào chỉ là tài liệu tham khảo. Với Kế toán, giữ dấu vết chứng từ–bút toán; với Marketing, giữ mã chiến dịch–brief–báo cáo. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu khóa tra cứu giúp đồng nghiệp tìm đúng bản.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Thử tìm lại bằng mắt của đồng nghiệp</h3><p>Giả sử bạn rời nhóm một tuần: người khác có biết tài liệu nằm đâu, bản nào được dùng và ai được hỏi khi số liệu sai không? Nếu câu trả lời là không, hãy sửa tên, sổ đăng ký hoặc quyền trước khi nộp. Khả năng tìm lại là tiêu chí thực tế của việc quản lý thông tin.</p><aside><h4>Kiểm thử truy xuất</h4><ul><li>01 · Có mã · Tìm trong sổ</li><li>02 · Có đường dẫn · Mở đúng bản</li><li>03 · Có chủ sở hữu · Hỏi khi cần</li></ul><p>Ba bước kiểm thử cho thấy một người khác có thể tìm và kiểm tra tài liệu.</p></aside><section><h4>Tự kiểm tra</h4><p>Tự tìm lại một tệp chỉ bằng mã và kỳ.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Ba bước kiểm thử cho thấy một người khác có thể tìm và kiểm tra tài liệu.","altText":"Ba bước kiểm thử cho thấy một người khác có thể tìm và kiểm tra tài liệu."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Thiết kế thư mục bàn giao có phiên bản</h3><p>Một bộ chứng từ mẫu gồm PDF gốc, bảng đối chiếu và bản xuất để đọc. Đặt tên theo kỳ–mã–chủ đề–phiên bản, ví dụ 2026-09_CP017_chung-tu_v01.pdf; không dùng “final_moi_nhat”. Giữ bản gốc ở thư mục chỉ đọc. Bản làm việc có phiên bản và người sửa; bản đã duyệt có ngày duyệt. Người kiểm tra chỉ cần quyền xem bản phù hợp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Thiết kế thư mục bàn giao có phiên bản</h3><p>Tổ chức bản gốc, bản làm việc và bản đã duyệt để truy xuất, phân quyền và đối chiếu. Thực hiện theo bốn bước: 1) Phân loại tệp: bản gốc, bản làm việc, bản đã duyệt. 2) Viết quy ước tên gồm kỳ, mã/chủ đề, phiên bản và phần mở rộng. 3) Vẽ cấu trúc thư mục và gán quyền xem/sửa cho từng vai trò. 4) Mô phỏng đổi v01 thành v02 và ghi nguyên nhân thay đổi. Sản phẩm cần tạo: Ảnh hoặc sơ đồ thư mục chứa ba tệp đặt tên theo quy ước, bảng quyền và một dòng nhật ký phiên bản.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Phân loại tệp: bản gốc, bản làm việc, bản đã duyệt.</li><li>02 · Viết quy ước tên gồm kỳ, mã/chủ đề, phiên bản và phần mở rộng.</li><li>03 · Vẽ cấu trúc thư mục và gán quyền xem/sửa cho từng vai trò.</li><li>04 · Mô phỏng đổi v01 thành v02 và ghi nguyên nhân thay đổi.</li></ul><p>Quy trình thực hành thiết kế thư mục bàn giao có phiên bản có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Quy trình thực hành thiết kế thư mục bàn giao có phiên bản có sản phẩm kiểm tra được.","altText":"Quy trình thực hành thiết kế thư mục bàn giao có phiên bản có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-F/M03/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Bản gốc không bị ghi đè. Tên tệp tự thể hiện được kỳ và phiên bản. Người chỉ cần đọc không có quyền chỉnh sửa toàn bộ thư mục. Lỗi thường gặp: Dùng tên “bản cuối” cho nhiều tệp và cấp quyền sửa cho bất kỳ ai có liên kết. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Bản gốc không bị ghi đè.</li><li>Tiêu chí 2 · Tên tệp tự thể hiện được kỳ và phiên bản.</li><li>Tiêu chí 3 · Người chỉ cần đọc không có quyền chỉnh sửa toàn bộ thư mục.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> National Archives · Quy ước đặt tên tệp · https://www.archives.gov/records-mgmt/bulletins/2015/2015-04-appendix-b.html</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Tên tệp nào dễ truy xuất và sắp xếp theo thời gian?","explanation":"Tên nhất quán với kỳ, chủ đề và phiên bản dễ tìm lại hơn.","options":[{"text":"bao_cao_final_moi.xlsx","isCorrect":false},{"text":"2026-09_bao-cao-kpi_v01.xlsx","isCorrect":true},{"text":"document1.xlsx","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Bạn cần lưu một bản gốc và một bản để chỉnh sửa. Cách nào phù hợp?","explanation":"Bản gốc cần giữ dấu vết; bản làm việc cần phiên bản rõ.","options":[{"text":"Ghi đè bản gốc sau mỗi lần sửa","isCorrect":false},{"text":"Giữ bản gốc, tạo bản làm việc có phiên bản và quyền phù hợp","isCorrect":true},{"text":"Chỉ gửi cả hai qua chat","isCorrect":false}]},{"text":"Đồng nghiệp chỉ cần đọc tài liệu đã chốt. Quyền nào là đủ?","explanation":"Cấp quyền tối thiểu theo nhu cầu công việc.","options":[{"text":"Xem bản đã duyệt","isCorrect":true},{"text":"Sửa tất cả tệp nguồn","isCorrect":false},{"text":"Quản trị kho dữ liệu","isCorrect":false}]},{"text":"Tên tệp “final_moi_nhat2.xlsx” gây khó khăn chính gì?","explanation":"Tên tệp có kỳ, chủ đề và phiên bản giúp tìm, sắp xếp và bàn giao.","options":[{"text":"Không thể mở bằng máy tính","isCorrect":false},{"text":"Không thể nhận ra kỳ, nội dung và phiên bản một cách nhất quán","isCorrect":true},{"text":"Tệp luôn quá lớn","isCorrect":false}]}]}]},{"code":"A1-I","title":"Chiến lược tìm kiếm và quản lý thông tin","outcome":"Thiết kế chiến lược tìm, so sánh nguồn khác định nghĩa và tổ chức hồ sơ thông tin cho nhóm.","final":{"title":"Bài cuối khóa M1-I · vị trí của bạn","promptHtml":"<h3>Tình huống</h3><p>Áp dụng vào một quyết định thực tế của vị trí.</p><h3>Yêu cầu</h3><p>Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.</p><h3>Các bước cần thực hiện</h3><ul><li>Viết nhu cầu thông tin có phạm vi, thời gian, mức chi tiết và sản phẩm đầu ra; lập ma trận từ khóa.</li><li>Ghi nhật ký ít nhất 8 truy vấn, sử dụng ít nhất 4 dạng toán tử hoặc cách lọc có giải thích.</li><li>Thu thập 5 nguồn, trong đó ít nhất 2 nguồn sơ cấp; so sánh định nghĩa, kỳ và phương pháp của chỉ số quan trọng.</li><li>Nộp brief 1 trang: điều đã biết, điều còn tranh cãi, con số hoặc khoảng giá trị khuyến nghị và lý do.</li></ul><h3>Sản phẩm cần nộp</h3><ul><li>Nhật ký nguồn và định nghĩa</li><li>Sản phẩm công việc có thể kiểm tra</li><li>Giới hạn và đề xuất tiếp theo</li></ul>","criteria":["Nhu cầu thông tin đầy đủ, cụ thể","Chiến lược tìm kiếm: ≥8 truy vấn, ≥4 toán tử","Chất lượng nguồn: ≥2 sơ cấp, đánh giá đầy đủ","Bảng so sánh, phát hiện khác biệt","Khuyến nghị có căn cứ"]},"modules":[{"title":"Chiến lược tìm kiếm và toán tử","quizTitle":"Ôn tập · Chiến lược tìm kiếm và toán tử","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S01\"><p><strong>01 / Lập kế hoạch</strong></p><h3>Đặt câu hỏi trước khi tìm</h3><p>Chốt đối tượng, chỉ tiêu, kỳ, địa bàn, mức chi tiết và sản phẩm cần nộp. Tạo ma trận từ khóa gồm thuật ngữ chính, từ đồng nghĩa và từ cần loại trừ. Ghi cả điều kiện dừng tìm khi đã đủ bằng chứng.</p><aside><h4>Kế hoạch tìm có điều kiện dừng</h4><ul><li>01 · Câu hỏi · Đối tượng · kỳ · phạm vi</li><li>02 · Từ khóa · Chính · đồng nghĩa</li><li>03 · Dừng · Đủ nguồn cho quyết định</li></ul><p>Ba giai đoạn tạo kế hoạch tìm trước khi mở công cụ.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết nhu cầu thông tin theo sáu yếu tố.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba giai đoạn tạo kế hoạch tìm trước khi mở công cụ.","altText":"Ba giai đoạn tạo kế hoạch tìm trước khi mở công cụ."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S02\"><p><strong>02 / Tinh chỉnh</strong></p><h3>Dùng toán tử có chủ đích</h3><p>Dấu ngoặc kép tìm cụm từ chính xác; site: giới hạn miền; filetype: lọc định dạng; dấu trừ loại chủ đề không liên quan; OR viết hoa tìm một trong hai thuật ngữ. Toán tử giúp lọc kết quả nhưng không tự xác nhận độ tin cậy của tài liệu. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Các toán tử có chức năng khác nhau</h4><ul><li>&quot;…&quot; · Khóa cụm từ</li><li>site: · Giới hạn website/miền</li><li>filetype: · Giới hạn định dạng</li></ul><p>Ba dòng ví dụ phân biệt lọc cụm từ, miền và định dạng trong truy vấn.</p></aside><section><h4>Tự kiểm tra</h4><p>Lập hai truy vấn khác nhau cho cùng nhu cầu.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba dòng ví dụ phân biệt lọc cụm từ, miền và định dạng trong truy vấn.","altText":"Ba dòng ví dụ phân biệt lọc cụm từ, miền và định dạng trong truy vấn."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S03\"><p><strong>03 / Nhật ký</strong></p><h3>Cho người khác lặp lại việc tìm</h3><p>Ghi truy vấn, công cụ, thời điểm, số kết quả đáng xem và lý do đổi truy vấn. Chỉ giữ các nguồn trả lời đúng phạm vi và kỳ; đánh dấu phần chưa tìm được thay vì kéo dài tìm kiếm vô hạn.</p><aside><h4>Nhật ký truy vấn</h4><ul><li>09:00 · Truy vấn rộng · Ít liên quan</li><li>09:10 · Thêm kỳ và site: · Đúng phạm vi</li><li>09:20 · Lưu nguồn · Có URL</li></ul><p>Trục thời gian cho thấy truy vấn được chỉnh và lý do dừng tìm.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn một quy tắc dừng tìm có lý do.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Trục thời gian cho thấy truy vấn được chỉnh và lý do dừng tìm.","altText":"Trục thời gian cho thấy truy vấn được chỉnh và lý do dừng tìm."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S04\"><p><strong>04 / Ma trận từ khóa</strong></p><h3>Tìm bằng các nhóm thuật ngữ</h3><p>Lập bảng gồm khái niệm chính, từ đồng nghĩa, tên hệ thống, kỳ và điều cần loại trừ. Ví dụ “doanh thu” có thể là doanh thu gộp hoặc thuần; “truy cập” có thể là nhấp hay phiên. Từ khóa phải phản ánh định nghĩa bạn đang cần, không chỉ một từ nghe quen.</p><aside><h4>Ma trận truy vấn</h4><ul><li>Khái niệm · Doanh thu / phiên</li><li>Đồng nghĩa · Tên cũ / tên mới</li><li>Giới hạn · 09/2026 · nguồn chính</li></ul><p>Phiếu ma trận chứa ba nhóm từ giúp truy vấn vừa đủ rộng vừa đúng phạm vi.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi hai từ đồng nghĩa và một từ cần loại.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Phiếu ma trận chứa ba nhóm từ giúp truy vấn vừa đủ rộng vừa đúng phạm vi.","altText":"Phiếu ma trận chứa ba nhóm từ giúp truy vấn vừa đủ rộng vừa đúng phạm vi."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S05\"><p><strong>05 / Toán tử</strong></p><h3>Dùng cú pháp để thu hẹp, không để xác thực</h3><p>Dấu ngoặc kép giữ nguyên cụm từ; site: thu hẹp trang hoặc miền; filetype: tìm định dạng. Kết hợp toán tử khi có lý do rõ, rồi mở từng kết quả để kiểm tra nguồn. Một PDF trên website uy tín vẫn có thể chứa số liệu không đúng kỳ hoặc không đúng câu hỏi.</p><aside><h4>Truy vấn minh họa</h4><ul><li>Cụm · &quot;báo cáo quý 3&quot;</li><li>Miền · site:gov.vn</li><li>Dạng · filetype:pdf</li></ul><p>Ba thành phần hợp thành truy vấn; hình không khẳng định kết quả tìm được là đúng.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một truy vấn và nói từng toán tử làm gì.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba thành phần hợp thành truy vấn; hình không khẳng định kết quả tìm được là đúng.","altText":"Ba thành phần hợp thành truy vấn; hình không khẳng định kết quả tìm được là đúng."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S06\"><p><strong>06 / Nhật ký</strong></p><h3>Lưu cả kết quả không được chọn</h3><p>Nhật ký tối thiểu có truy vấn, thời điểm, nguồn mở, lý do chọn hoặc loại và khoảng trống còn lại. Người khác cần hiểu vì sao báo cáo A được dùng thay B. Nếu tài liệu gốc không mở được, ghi trạng thái đó thay vì tự điền nội dung từ đoạn trích.</p><aside><h4>Ba lần thử có lý do</h4><ul><li>Lần 1 · Rộng · nhiễu</li><li>Lần 2 · Thêm kỳ</li><li>Lần 3 · Nguồn gốc phù hợp</li></ul><p>Trục nhật ký thể hiện mỗi lần đổi truy vấn đều có lý do và kết quả.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một dòng nhật ký cho nguồn đã loại.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Trục nhật ký thể hiện mỗi lần đổi truy vấn đều có lý do và kết quả.","altText":"Trục nhật ký thể hiện mỗi lần đổi truy vấn đều có lý do và kết quả."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Lập kế hoạch tìm phục vụ quyết định</h3><p>Trong ca của vị trí, ghi quyết định cần hỗ trợ rồi tìm ít nhất hai hệ thống nguồn có định nghĩa rõ. Kế toán có thể cần sổ cái và hóa đơn; Marketing cần GA4 và nền tảng quảng cáo. Không trộn các chỉ tiêu khác đơn vị đếm vào một tổng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi một câu hỏi quyết định và hai nguồn cần truy.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Biết khi nào ngừng tìm</h3><p>Dừng khi đã có nguồn gốc đáp ứng đúng phạm vi, đủ căn cứ để trả lời và đã ghi giới hạn còn lại. Không dừng chỉ vì có con số đầu tiên; cũng không tìm vô hạn để loại mọi bất định. Nêu rõ điều gì sẽ khiến phải mở lại việc tìm kiếm.</p><aside><h4>Quy tắc dừng</h4><ul><li>Đủ · Nguồn · kỳ · định nghĩa rõ</li><li>Còn thiếu · Ghi khoảng trống</li><li>Mở lại · Khi giả định đổi</li></ul><p>Ba ô quyết định cho biết khi nào kết thúc hoặc lặp lại quá trình tìm.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết điều kiện dừng và một điều kiện mở lại.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba ô quyết định cho biết khi nào kết thúc hoặc lặp lại quá trình tìm.","altText":"Ba ô quyết định cho biết khi nào kết thúc hoặc lặp lại quá trình tìm."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Lập chiến lược tìm kiếm phục vụ quyết định</h3><p>Để so hiệu quả một chiến dịch theo tháng, không tìm “chiến dịch tốt không”. Hãy xác định quyết định cần hỗ trợ, kỳ, phạm vi, chỉ số và nơi tạo số liệu. Truy vấn có thể dùng cụm từ trong ngoặc kép, site: để giới hạn miền, filetype: để tìm PDF, dấu trừ để loại từ và OR viết hoa để thử hai thuật ngữ tương đương; sau đó vẫn phải mở tài liệu để xác nhận định nghĩa và kỳ. Dừng khi có đủ nguồn cho từng chỉ số hoặc ghi khoảng trống rõ ràng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Lập chiến lược tìm kiếm phục vụ quyết định</h3><p>Xác định câu hỏi, nguồn ưu tiên, truy vấn và điều kiện dừng trước khi tìm sâu. Thực hiện theo bốn bước: 1) Ghi một quyết định và hai chỉ số có thể làm đổi quyết định. 2) Lập ma trận từ khóa và ghi ít nhất năm lần tinh chỉnh truy vấn; dùng toán tử phù hợp, giải thích tác dụng. 3) Xếp thứ tự nguồn nội bộ/chính thức/thứ cấp; ghi lý do. 4) Lập tiêu chí dừng và nhật ký kết quả tìm/không tìm được. Sản phẩm cần tạo: Kế hoạch tìm có ma trận từ khóa, ít nhất năm bước tinh chỉnh, nguồn và điều kiện dừng.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Ghi một quyết định và hai chỉ số có thể làm đổi quyết định.</li><li>02 · Lập ma trận từ khóa và ghi ít nhất năm lần tinh chỉnh truy vấn; dùng toán tử phù hợp, giải thích tác dụng.</li><li>03 · Xếp thứ tự nguồn nội bộ/chính thức/thứ cấp; ghi lý do.</li><li>04 · Lập tiêu chí dừng và nhật ký kết quả tìm/không tìm được.</li></ul><p>Quy trình thực hành lập chiến lược tìm kiếm phục vụ quyết định có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Quy trình thực hành lập chiến lược tìm kiếm phục vụ quyết định có sản phẩm kiểm tra được.","altText":"Quy trình thực hành lập chiến lược tìm kiếm phục vụ quyết định có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-I/M01/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Toán tử tìm kiếm được dùng để lọc, không được coi là xác nhận tính đúng. Mỗi chỉ số có định nghĩa và kỳ cần tìm. Khoảng trống nguồn được ghi lại thay vì tự điền số. Lỗi thường gặp: Thu thật nhiều kết quả mà không biết kết quả nào phục vụ quyết định. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Toán tử tìm kiếm được dùng để lọc, không được coi là xác nhận tính đúng.</li><li>Tiêu chí 2 · Mỗi chỉ số có định nghĩa và kỳ cần tìm.</li><li>Tiêu chí 3 · Khoảng trống nguồn được ghi lại thay vì tự điền số.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Google · Cách tinh chỉnh kết quả tìm kiếm · https://support.google.com/websearch/answer/2466433?hl=en</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Truy vấn nào giới hạn nguồn và định dạng?","explanation":"site: và filetype: phải gắn liền với giá trị; dấu ngoặc kép khóa cụm từ.","options":[{"text":"\"báo cáo thị trường\" site:gov.vn filetype:pdf","isCorrect":true},{"text":"báo cáo thị trường mới nhất đúng nhất","isCorrect":false},{"text":"filetype pdf site gov vn báo cáo","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Toán tử site: giúp việc gì?","explanation":"site: là bộ lọc phạm vi tìm, không phải phép xác thực.","options":[{"text":"Xác nhận mọi tài liệu trên trang đều đúng","isCorrect":false},{"text":"Giới hạn kết quả theo website hoặc miền","isCorrect":true},{"text":"Tìm tệp PDF ở mọi nơi","isCorrect":false}]},{"text":"Truy vấn đầu cho quá nhiều kết quả. Bước tiếp theo hợp lý?","explanation":"Tinh chỉnh truy vấn có căn cứ và giữ nhật ký để lặp lại.","options":[{"text":"Bỏ câu hỏi công việc","isCorrect":false},{"text":"Thêm kỳ, đối tượng hoặc từ đồng nghĩa rồi ghi lại thay đổi","isCorrect":true},{"text":"Chỉ chọn kết quả đầu","isCorrect":false}]},{"text":"Khi nào nên dừng tìm?","explanation":"Điều kiện dừng gắn với nhu cầu quyết định, không với số lượng kết quả tùy ý.","options":[{"text":"Ngay sau kết quả đầu tiên","isCorrect":false},{"text":"Khi đã có nguồn đủ phù hợp cho quyết định và ghi rõ phần còn thiếu","isCorrect":true},{"text":"Chỉ khi toàn bộ Internet được xem","isCorrect":false}]}]},{"title":"Đánh giá và so sánh nguồn tin","quizTitle":"Ôn tập · Đánh giá và so sánh nguồn tin","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S01\"><p><strong>01 / Nguồn gốc</strong></p><h3>Phân biệt sơ cấp và thứ cấp</h3><p>Nguồn sơ cấp là nơi dữ liệu được tạo ra; nguồn thứ cấp diễn giải hoặc trích lại. Nhiều bài cùng dẫn một báo cáo không phải nhiều xác nhận độc lập. Lưu đường dẫn tới tài liệu gốc và mô tả cách thu thập.</p><aside><h4>Dòng gốc của chỉ số</h4><ul><li>Bản gốc · Hệ thống tạo dữ liệu</li><li>Báo cáo · Tổng hợp từ bản gốc</li><li>Bài viết · Diễn giải lại</li></ul><p>Sơ đồ phân biệt dữ liệu sơ cấp, báo cáo tổng hợp và bài diễn giải.</p></aside><section><h4>Tự kiểm tra</h4><p>Chỉ ra nguồn gốc của một chỉ số.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Sơ đồ phân biệt dữ liệu sơ cấp, báo cáo tổng hợp và bài diễn giải.","altText":"Sơ đồ phân biệt dữ liệu sơ cấp, báo cáo tổng hợp và bài diễn giải."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S02\"><p><strong>02 / Định nghĩa</strong></p><h3>Hai số khác nhau vì sao?</h3><p>Trước khi tính trung bình hay chọn số lớn hơn, so định nghĩa chỉ tiêu, mẫu số, kỳ, phạm vi, đơn vị và cách lọc. Các số có thể đều đúng trong phạm vi riêng nhưng không cộng hoặc so trực tiếp được. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Cùng tên, khác cách đo</h4><ul><li>Báo cáo A · Tháng 9 · doanh thu gộp</li><li>Báo cáo B · Tháng 9 · doanh thu thuần</li></ul><p>Hai cột doanh thu có cùng kỳ nhưng định nghĩa khác nên chưa so trực tiếp.</p></aside><section><h4>Tự kiểm tra</h4><p>Lập bảng so sánh hai con số mâu thuẫn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Hai cột doanh thu có cùng kỳ nhưng định nghĩa khác nên chưa so trực tiếp.","altText":"Hai cột doanh thu có cùng kỳ nhưng định nghĩa khác nên chưa so trực tiếp."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S03\"><p><strong>03 / Kết luận</strong></p><h3>Nêu con số kèm giới hạn</h3><p>Chọn số phù hợp quyết định cần đưa ra và giải thích nguồn, cách đo, độ mới, độ tin cậy. Nếu chưa thể hòa giải, báo cáo khoảng ước lượng hoặc hai cách hiểu; ghi việc phải kiểm tra tiếp.</p><aside><h4>Kết luận có giới hạn</h4><ul><li>Dùng được · Định nghĩa khớp quyết định</li><li>Chưa dùng · Chưa rõ kỳ hoặc phạm vi</li><li>Việc tiếp · Xác minh nguồn gốc</li></ul><p>Ba trạng thái cho quyết định dùng, tạm giữ hoặc kiểm tra thêm một chỉ số.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết kết luận hai câu có điều kiện sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba trạng thái cho quyết định dùng, tạm giữ hoặc kiểm tra thêm một chỉ số.","altText":"Ba trạng thái cho quyết định dùng, tạm giữ hoặc kiểm tra thêm một chỉ số."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S04\"><p><strong>04 / Bảng so nguồn</strong></p><h3>So những thuộc tính tạo ra khác biệt</h3><p>Lập mỗi hàng là một nguồn; các cột gồm người tạo, kỳ, phạm vi, đơn vị, phương pháp và tình trạng duyệt. Chỉ sau khi cột khớp mới so các con số. Nếu không khớp, nêu rõ khác biệt nào có thể giải thích chênh lệch và khác biệt nào cần xác minh.</p><aside><h4>Hai bản ghi cần so</h4><ul><li>Bản A · Kỳ 09 · doanh thu gộp</li><li>Bản B · Kỳ 09 · doanh thu thuần</li><li>Điểm lệch · Định nghĩa chỉ tiêu</li></ul><p>Bảng so nhấn mạnh khác biệt định nghĩa trước khi tính chênh lệch.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo ba cột so sánh quan trọng nhất của ca học.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Bảng so nhấn mạnh khác biệt định nghĩa trước khi tính chênh lệch.","altText":"Bảng so nhấn mạnh khác biệt định nghĩa trước khi tính chênh lệch."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S05\"><p><strong>05 / Phạm vi đo</strong></p><h3>Không đồng nhất nhấp, phiên và người dùng</h3><p>Một lượt nhấp quảng cáo là hành động trên nền tảng quảng cáo; phiên và người dùng là chỉ số của công cụ phân tích với phạm vi đo riêng. Chênh lệch không tự chứng minh lỗi. Cần kiểm tra thẻ đo, UTM, múi giờ, bộ lọc và phạm vi báo cáo trước khi giải thích.</p><aside><h4>Ba đơn vị khác nhau</h4><ul><li>Nhấp · 1.200 · nền tảng quảng cáo</li><li>Phiên · 980 · GA4</li><li>Người mới · 740 · GA4</li></ul><p>Ba ô số giả lập dùng ba đơn vị đếm khác nhau, không phải ba giai đoạn của cùng một phễu đã đối soát.</p></aside><section><h4>Tự kiểm tra</h4><p>Nói vì sao 1.200 nhấp không thể lấy trừ trực tiếp 980 phiên để kết luận mất 220 người.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba ô số giả lập dùng ba đơn vị đếm khác nhau, không phải ba giai đoạn của cùng một phễu đã đối soát.","altText":"Ba ô số giả lập dùng ba đơn vị đếm khác nhau, không phải ba giai đoạn của cùng một phễu đã đối soát."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S06\"><p><strong>06 / Giải thích chênh</strong></p><h3>Giả thuyết phải có phép kiểm tra</h3><p>Với mỗi nguyên nhân dự đoán, ghi cách kiểm chứng. Nếu nghi lệch kỳ, so múi giờ và ngày chốt; nếu nghi thiếu UTM, kiểm tra liên kết; nếu nghi bản ghi trùng, xem mã giao dịch hoặc lead. Đừng kết luận lỗi hệ thống chỉ từ hai tổng không bằng nhau.</p><aside><h4>Giả thuyết có kiểm tra</h4><ul><li>Giả thuyết · Khác múi giờ</li><li>Phép thử · So ngày theo cùng múi giờ</li><li>Kết quả · Ghi số dòng thay đổi</li></ul><p>Phiếu giả thuyết buộc người phân tích nêu phép thử thay vì đoán nguyên nhân.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một giả thuyết và phép thử tương ứng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Phiếu giả thuyết buộc người phân tích nêu phép thử thay vì đoán nguyên nhân.","altText":"Phiếu giả thuyết buộc người phân tích nêu phép thử thay vì đoán nguyên nhân."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Chọn số phù hợp câu hỏi quản lý</h3><p>Kế toán cần số phù hợp định nghĩa doanh thu và trạng thái hóa đơn; Marketing cần chỉ số đúng mục tiêu chiến dịch. Trình bày cả nguồn không chọn và lý do. Khi chưa thể hòa giải, dùng hai kịch bản có điều kiện hoặc nêu bước xác minh tiếp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn chỉ số cho quyết định và nêu một giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Viết một brief không che giấu bất định</h3><p>Brief một trang nên có câu hỏi, bảng nguồn, chênh lệch được giải thích, điều chưa giải thích và khuyến nghị. Người đọc phải phân biệt quan sát thực tế với giả định. Dùng câu kết luận có điều kiện nếu một định nghĩa hoặc nguồn vẫn chưa được xác nhận.</p><aside><h4>Brief quyết định</h4><ul><li>01 · Nguồn · Định nghĩa · kỳ</li><li>02 · Đối chiếu · Khớp và chưa khớp</li><li>03 · Đề xuất · Có điều kiện</li></ul><p>Ba phần cốt lõi của brief kết nối nguồn, phân tích và hành động.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết khuyến nghị hai câu với điều kiện áp dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba phần cốt lõi của brief kết nối nguồn, phân tích và hành động.","altText":"Ba phần cốt lõi của brief kết nối nguồn, phân tích và hành động."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Lập bảng so hai báo cáo không đồng nhất</h3><p>Báo cáo A là doanh thu đã ghi nhận, báo cáo B là hóa đơn đã xuất. Hai tổng có thể lệch vì hóa đơn hủy hoặc thời điểm ghi nhận. Tương tự, lượt nhấp quảng cáo, phiên GA4 và người dùng mới là ba đơn vị đếm khác nhau; không lấy trung bình hay trừ trực tiếp để gọi là “sai lệch”. Bảng so phải có cột đơn vị đếm, kỳ, bộ lọc, trạng thái và nguồn gốc. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Lập bảng so hai báo cáo không đồng nhất</h3><p>Giải thích chênh lệch bằng định nghĩa, phạm vi, kỳ và trạng thái trước khi khuyến nghị. Thực hiện theo bốn bước: 1) Chọn ba nguồn cùng chủ đề; ghi số, đơn vị đếm và loại nguồn sơ cấp/thứ cấp. 2) So tác giả, thời điểm, mục đích, bằng chứng, khả năng kiểm chứng, định nghĩa và kỳ. 3) Truy một bản ghi/hóa đơn/chiến dịch mẫu để xác minh nguyên nhân chênh lệch. 4) Viết khuyến nghị có điều kiện và một bước đối soát tiếp. Sản phẩm cần tạo: Ma trận ba nguồn theo năm tiêu chí, bảng giải thích chênh lệch và brief quyết định một trang.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Chọn ba nguồn cùng chủ đề; ghi số, đơn vị đếm và loại nguồn sơ cấp/thứ cấp.</li><li>02 · So tác giả, thời điểm, mục đích, bằng chứng, khả năng kiểm chứng, định nghĩa và kỳ.</li><li>03 · Truy một bản ghi/hóa đơn/chiến dịch mẫu để xác minh nguyên nhân chênh lệch.</li><li>04 · Viết khuyến nghị có điều kiện và một bước đối soát tiếp.</li></ul><p>Quy trình thực hành lập bảng so hai báo cáo không đồng nhất có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Quy trình thực hành lập bảng so hai báo cáo không đồng nhất có sản phẩm kiểm tra được.","altText":"Quy trình thực hành lập bảng so hai báo cáo không đồng nhất có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-I/M02/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Không so trực tiếp các chỉ số khác phạm vi. Mỗi nguyên nhân chênh lệch có bằng chứng hoặc được ghi là giả định. Kết luận cho biết số nào dùng được cho câu hỏi nào. Lỗi thường gặp: Lấy trung bình hai tổng khi một số gồm giao dịch hủy còn số kia không. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Không so trực tiếp các chỉ số khác phạm vi.</li><li>Tiêu chí 2 · Mỗi nguyên nhân chênh lệch có bằng chứng hoặc được ghi là giả định.</li><li>Tiêu chí 3 · Kết luận cho biết số nào dùng được cho câu hỏi nào.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Hai báo cáo cho cùng tên chỉ tiêu nhưng khác số. Bước đầu là gì?","explanation":"Khác biệt phạm vi hoặc phương pháp phải được giải thích trước khi chọn số.","options":[{"text":"Chọn số cao hơn","isCorrect":false},{"text":"So định nghĩa, kỳ và phạm vi đo","isCorrect":true},{"text":"Lấy trung bình cộng","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Hai báo cáo cùng tên “doanh thu” nhưng khác tổng. Kiểm tra gì trước?","explanation":"Tên chỉ số giống nhau chưa bảo đảm cùng cách đo.","options":[{"text":"Màu biểu đồ","isCorrect":false},{"text":"Định nghĩa gộp/thuần, kỳ, trạng thái giao dịch và phạm vi","isCorrect":true},{"text":"Chọn số trung bình","isCorrect":false}]},{"text":"Một ảnh biểu đồ không ghi kỳ và mẫu số. Bạn nên?","explanation":"Bản gốc và phương pháp là căn cứ của con số.","options":[{"text":"Dùng để chốt báo cáo","isCorrect":false},{"text":"Tìm báo cáo gốc và xác nhận định nghĩa trước khi dùng","isCorrect":true},{"text":"Ước lượng mẫu số theo hình","isCorrect":false}]},{"text":"Khi chưa hòa giải được hai số, báo cáo nên viết gì?","explanation":"Bất định cần thể hiện rõ cho người ra quyết định.","options":[{"text":"Một số duy nhất không chú thích","isCorrect":false},{"text":"Hai kịch bản có điều kiện cùng bước xác minh tiếp","isCorrect":true},{"text":"Bỏ hẳn phần số liệu","isCorrect":false}]}]},{"title":"Tổ chức và quản lý kho thông tin","quizTitle":"Ôn tập · Tổ chức và quản lý kho thông tin","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S01\"><p><strong>01 / Cấu trúc</strong></p><h3>Một nguyên tắc phân loại</h3><p>Chọn cách phân loại chính theo dự án hoặc loại hồ sơ rồi dùng nhất quán. Tránh pha hai cách cùng cấp khiến người dùng không biết lưu ở đâu. Giữ cây thư mục đủ nông để người khác tìm được.</p><aside><h4>Một cây thư mục nhất quán</h4><ul><li>Chiến dịch 2026 · Thư mục gốc</li><li>01_Nguồn · Tệp gốc</li><li>02_Phân tích · Bản làm việc</li><li>03_Duyệt · Bản chốt</li></ul><p>Cây thư mục ví dụ được sắp theo một nguyên tắc từ nguồn tới bản duyệt.</p></aside><section><h4>Tự kiểm tra</h4><p>Vẽ cấu trúc thư mục cho một chu kỳ công việc.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Cây thư mục ví dụ được sắp theo một nguyên tắc từ nguồn tới bản duyệt.","altText":"Cây thư mục ví dụ được sắp theo một nguyên tắc từ nguồn tới bản duyệt."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S02\"><p><strong>02 / Sổ đăng ký</strong></p><h3>Thư mục chưa đủ để quản lý</h3><p>Sổ đăng ký ghi tên, phiên bản, nguồn, kỳ dữ liệu, chủ sở hữu, mức nhạy cảm và liên kết. Nó giúp tra cứu theo thuộc tính mà cây thư mục không thể hiện hết. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Sổ đăng ký dữ liệu</h4><ul><li>Tên · KPI_09_2026</li><li>Nguồn · Hệ thống gốc</li><li>Phiên bản · v02 · 02/10/2026</li></ul><p>Ba trường mẫu trong sổ đăng ký liên kết tệp với nguồn và phiên bản.</p></aside><section><h4>Tự kiểm tra</h4><p>Liệt kê các trường bắt buộc của sổ đăng ký.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Ba trường mẫu trong sổ đăng ký liên kết tệp với nguồn và phiên bản.","altText":"Ba trường mẫu trong sổ đăng ký liên kết tệp với nguồn và phiên bản."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S03\"><p><strong>03 / Quyền truy cập</strong></p><h3>Cấp đúng người, đúng mục đích</h3><p>Áp dụng quyền tối thiểu: mỗi người chỉ có quyền đủ để làm phần việc. Đồng bộ tệp không thay thế bản sao lưu; một thay đổi sai cũng có thể đồng bộ sang các bản khác.</p><aside><h4>Quyền theo nhiệm vụ</h4><ul><li>Người soạn · Được sửa bản làm việc</li><li>Người duyệt · Được xem và duyệt</li><li>Người đọc · Chỉ xem bản đã chốt</li></ul><p>Ba mức quyền minh họa nguyên tắc chỉ cấp quyền cần cho công việc.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu ai được xem, ai được sửa và nơi sao lưu.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Ba mức quyền minh họa nguyên tắc chỉ cấp quyền cần cho công việc.","altText":"Ba mức quyền minh họa nguyên tắc chỉ cấp quyền cần cho công việc."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S04\"><p><strong>04 / Phân loại</strong></p><h3>Một kho thông tin cần quy ước chung</h3><p>Chọn cách phân loại phản ánh hành trình công việc: nguồn gốc, bản đang xử lý, bản duyệt và lưu trữ. Tránh để mỗi cá nhân tạo một cây riêng. Khi một tệp thuộc nhiều chủ đề, lưu một bản chính và dùng metadata hoặc liên kết để tìm lại, giảm trùng lặp.</p><aside><h4>Một bản chính</h4><ul><li>Kho dữ liệu · Gốc</li><li>01_Nguồn · Bản chính</li><li>02_Làm-việc · Bản phân tích</li><li>03_Duyệt · Bản công bố</li></ul><p>Cây thư mục thể hiện một bản chính và các trạng thái xử lý.</p></aside><section><h4>Tự kiểm tra</h4><p>Đề xuất thư mục gốc và ba thư mục con.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Cây thư mục thể hiện một bản chính và các trạng thái xử lý.","altText":"Cây thư mục thể hiện một bản chính và các trạng thái xử lý."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S05\"><p><strong>05 / Metadata</strong></p><h3>Sổ đăng ký giúp tìm bằng thuộc tính</h3><p>Bên cạnh đường dẫn, ghi tên bộ dữ liệu, hệ thống nguồn, chủ sở hữu, kỳ, phiên bản, ngày cập nhật và mức nhạy cảm. Nhờ vậy người dùng biết bảng nào đã chốt và hỏi ai khi có sai lệch. Không dùng tên file “mới nhất” như một trường trạng thái đáng tin.</p><aside><h4>Một dòng sổ đăng ký</h4><ul><li>Bộ dữ liệu · Báo cáo kỳ 09</li><li>Nguồn · Hệ thống chính</li><li>Chủ sở hữu · Người chịu trách nhiệm</li><li>Phiên bản · v02 · đã duyệt</li></ul><p>Dòng metadata mẫu làm rõ nguồn, người phụ trách và phiên bản của báo cáo.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn bảy trường sổ đăng ký cho ca học.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Dòng metadata mẫu làm rõ nguồn, người phụ trách và phiên bản của báo cáo.","altText":"Dòng metadata mẫu làm rõ nguồn, người phụ trách và phiên bản của báo cáo."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S06\"><p><strong>06 / Quyền và sao lưu</strong></p><h3>Quyền xem không đồng nghĩa quyền sửa</h3><p>Gắn quyền cho vai trò thực tế: người soạn sửa bản làm việc, người duyệt đọc và phê duyệt, người nhận chỉ xem bản chốt. Kiểm tra nơi lưu bản sao và khả năng khôi phục. Đồng bộ tệp là cơ chế cập nhật giữa thiết bị, không thay thế kiểm tra sao lưu.</p><aside><h4>Ma trận quyền</h4><ul><li>Soạn · Sửa bản làm việc</li><li>Duyệt · Xem · xác nhận</li><li>Nhận · Xem bản chốt</li></ul><p>Ba hàng quyền được gắn với nhiệm vụ cụ thể, không cấp quản trị cho mọi người.</p></aside><section><h4>Tự kiểm tra</h4><p>Phân hai quyền và một người chịu trách nhiệm sao lưu.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Ba hàng quyền được gắn với nhiệm vụ cụ thể, không cấp quản trị cho mọi người.","altText":"Ba hàng quyền được gắn với nhiệm vụ cụ thể, không cấp quản trị cho mọi người."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Tổ chức hồ sơ để người khác kiểm tra</h3><p>Với Kế toán, sổ đăng ký nối số chứng từ, bút toán và trạng thái điều chỉnh. Với Marketing, nối mã chiến dịch, nguồn GA4, quy ước UTM và thời điểm xuất báo cáo. Cả hai cần người phụ trách định nghĩa chỉ số, không chỉ một thư mục đẹp. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi khóa liên kết giữa hai hệ thống của ca học.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Thử tình huống bàn giao nhóm</h3><p>Một đồng nghiệp mới phải tìm được báo cáo đúng kỳ, mở nguồn gốc và biết ai phê duyệt mà không hỏi tác giả. Nếu không làm được, cần sửa sổ đăng ký, đường dẫn hoặc quyền. Đây là kiểm thử quản lý thông tin, không chỉ kiểm tra kỹ năng đặt tên.</p><aside><h4>Kiểm tra bàn giao</h4><ul><li>01 · Tìm · Theo mã · kỳ</li><li>02 · Mở · Đúng nguồn và bản</li><li>03 · Xác nhận · Người duyệt</li></ul><p>Ba bước kiểm thử giúp đánh giá kho thông tin có dùng được bởi người khác.</p></aside><section><h4>Tự kiểm tra</h4><p>Nhờ người khác tìm một bộ dữ liệu từ mã và kỳ.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Ba bước kiểm thử giúp đánh giá kho thông tin có dùng được bởi người khác.","altText":"Ba bước kiểm thử giúp đánh giá kho thông tin có dùng được bởi người khác."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Tạo sổ đăng ký nguồn và ma trận quyền</h3><p>Sổ đăng ký cho một báo cáo cần ghi tên hệ thống, người tạo, định nghĩa chỉ số, kỳ, URL/mã tệp, phiên bản và người phê duyệt. Bảng đối chiếu chỉ người phụ trách được sửa; quản lý nhận bản đọc. Khi dữ liệu kỳ trước được cập nhật, tạo dòng phiên bản mới và nêu tác động tới kết luận cũ thay vì ghi đè âm thầm. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Tạo sổ đăng ký nguồn và ma trận quyền</h3><p>Giữ định nghĩa, chủ sở hữu và lịch sử thay đổi của các nguồn dùng trong báo cáo. Thực hiện theo bốn bước: 1) Thiết kế cây thư mục tối đa bốn cấp và sổ đăng ký tối thiểu 20 tài liệu giả lập với tên, chủ đề, phiên bản, người phụ trách. 2) Gán chủ sở hữu, người duyệt và người chỉ xem; ghi nơi lưu bản sao có thể khôi phục. 3) Mô phỏng nguồn A đổi định nghĩa hoặc phiên bản; ghi tác động. 4) Kiểm tra một đồng nghiệp có thể dựng lại báo cáo theo sổ đăng ký và quy tắc phân loại. Sản phẩm cần tạo: Ảnh hoặc sơ đồ thư mục tối đa bốn cấp, sổ đăng ký ít nhất 20 dòng, ma trận quyền và quy tắc phân loại.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Thiết kế cây thư mục tối đa bốn cấp và sổ đăng ký tối thiểu 20 tài liệu giả lập với tên, chủ đề, phiên bản, người phụ trách.</li><li>02 · Gán chủ sở hữu, người duyệt và người chỉ xem; ghi nơi lưu bản sao có thể khôi phục.</li><li>03 · Mô phỏng nguồn A đổi định nghĩa hoặc phiên bản; ghi tác động.</li><li>04 · Kiểm tra một đồng nghiệp có thể dựng lại báo cáo theo sổ đăng ký và quy tắc phân loại.</li></ul><p>Quy trình thực hành tạo sổ đăng ký nguồn và ma trận quyền có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Quy trình thực hành tạo sổ đăng ký nguồn và ma trận quyền có sản phẩm kiểm tra được.","altText":"Quy trình thực hành tạo sổ đăng ký nguồn và ma trận quyền có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-I/M03/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Nguồn có định nghĩa, kỳ và phiên bản. Quyền sửa được giới hạn theo trách nhiệm. Số cũ có thể giải thích sau khi nguồn thay đổi. Lỗi thường gặp: Chia sẻ liên kết sửa cho cả phòng ban để “tiện” rồi không biết ai đổi dữ liệu. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Nguồn có định nghĩa, kỳ và phiên bản.</li><li>Tiêu chí 2 · Quyền sửa được giới hạn theo trách nhiệm.</li><li>Tiêu chí 3 · Số cũ có thể giải thích sau khi nguồn thay đổi.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> NIST · Nguyên tắc quyền tối thiểu · https://csrc.nist.gov/glossary/term/least_privilege</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Đồng nghiệp chỉ cần đọc báo cáo đã duyệt. Quyền nào phù hợp?","explanation":"Quyền tối thiểu chỉ cấp mức cần để thực hiện công việc.","options":[{"text":"Chỉnh sửa cả thư mục nguồn","isCorrect":false},{"text":"Quyền xem bản đã duyệt","isCorrect":true},{"text":"Quyền quản trị hệ thống","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Sổ đăng ký nguồn cần ghi bộ thông tin nào?","explanation":"Sổ đăng ký cần đủ thông tin truy vết và quản lý truy cập.","options":[{"text":"Tên nguồn, chủ sở hữu, kỳ, định nghĩa, phiên bản và quyền","isCorrect":true},{"text":"Chỉ tên người tải","isCorrect":false},{"text":"Chỉ đường dẫn chia sẻ công khai","isCorrect":false}]},{"text":"Một tệp chứa dữ liệu nhân sự chỉ người phụ trách cần sửa. Thiết lập nào đúng?","explanation":"Quyền theo vai trò và nhu cầu sử dụng, tránh cấp rộng.","options":[{"text":"Ai có link cũng sửa được","isCorrect":false},{"text":"Người phụ trách sửa; người cần đối chiếu chỉ xem phần phù hợp","isCorrect":true},{"text":"Không ai được xem kể cả người phụ trách","isCorrect":false}]},{"text":"Báo cáo tháng trước bị thay mà không ghi phiên bản. Rủi ro chính?","explanation":"Lịch sử thay đổi giúp kiểm tra và giải thích quyết định đã đưa ra.","options":[{"text":"Màu sắc thay đổi","isCorrect":false},{"text":"Không giải thích được vì sao kết quả cũ và mới khác nhau","isCorrect":true},{"text":"Tên tệp ngắn hơn","isCorrect":false}]}]}]},{"code":"A1-A","title":"Phân tích thông tin và quản trị dữ liệu","outcome":"Dẫn dắt nghiên cứu đa nguồn, đo chất lượng dữ liệu và thiết lập chuẩn quản trị cho quyết định quan trọng.","final":{"title":"Bài cuối khóa M1-A · vị trí của bạn","promptHtml":"<h3>Tình huống</h3><p>Áp dụng vào một quyết định thực tế của vị trí.</p><h3>Yêu cầu</h3><p>Nêu nhu cầu, nguồn, cách kiểm tra, sản phẩm công việc và kết luận có giới hạn.</p><h3>Các bước cần thực hiện</h3><ul><li>Lập kế hoạch nghiên cứu 4 bước, phối hợp nguồn nội bộ và bên ngoài, ghi khoảng trống và giả định.</li><li>Chấm sáu chiều chất lượng bằng phép đo có tử số, mẫu số/ngưỡng; viết ít nhất 6 quy tắc kiểm tra và phân loại phòng ngừa hoặc phát hiện.</li><li>Tạo từ điển tối thiểu 10 trường, phân vai chủ sở hữu, người quản lý dữ liệu và người vận hành; xác định nguồn chính thức.</li><li>Lập lịch lưu trữ và hủy cho 3 loại dữ liệu theo chính sách áp dụng; viết khuyến nghị, độ tin cậy và giới hạn.</li></ul><h3>Sản phẩm cần nộp</h3><ul><li>Nhật ký nguồn và định nghĩa</li><li>Sản phẩm công việc có thể kiểm tra</li><li>Giới hạn và đề xuất tiếp theo</li></ul>","criteria":["Kế hoạch và thực hiện nghiên cứu đa nguồn","Đánh giá chất lượng định lượng sáu chiều","Bộ tài liệu quản trị hoàn chỉnh","Báo cáo có khuyến nghị và giới hạn"]},"modules":[{"title":"Nghiên cứu phức hợp đa nguồn","quizTitle":"Ôn tập · Nghiên cứu phức hợp đa nguồn","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S01\"><p><strong>01 / Quyết định</strong></p><h3>Bắt đầu bằng quyết định cần hỗ trợ</h3><p>Nêu quyết định, phương án có thể chọn, ngưỡng rủi ro, chỉ tiêu và thời hạn. Tách điều đã biết, giả định và dữ liệu còn thiếu. Không thu thập “mọi thứ” khi chưa biết kết quả dùng để quyết định gì.</p><aside><h4>Nghiên cứu bắt đầu ở quyết định</h4><ul><li>Quyết định · Có mở rộng thị trường?</li><li>Chỉ tiêu · Nhu cầu · chi phí · rủi ro</li><li>Thời điểm · Trước kỳ ngân sách</li></ul><p>Khung quyết định xác định câu hỏi, tiêu chí và hạn trước khi thu thập.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một câu quyết định và hai chỉ tiêu.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Khung quyết định xác định câu hỏi, tiêu chí và hạn trước khi thu thập.","altText":"Khung quyết định xác định câu hỏi, tiêu chí và hạn trước khi thu thập."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S02\"><p><strong>02 / Thiết kế nguồn</strong></p><h3>Phối hợp nội bộ và bên ngoài</h3><p>Nguồn bên ngoài cho bối cảnh thị trường hoặc chuẩn tham chiếu; nguồn nội bộ cho vị thế thực tế của doanh nghiệp. Đánh dấu mức độc lập và phương pháp từng nguồn. Ba bản sao của một báo cáo không phải ba nguồn độc lập. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Bản đồ nguồn độc lập</h4><ul><li>Bên ngoài · Bối cảnh thị trường</li><li>Nội bộ · Bán hàng · tài chính</li><li>Đối chiếu · Phương pháp · phạm vi</li></ul><p>Hai nhóm nguồn ngoài/nội bộ cùng đi vào bước đối chiếu; bản sao cùng nguồn không được tính độc lập.</p></aside><section><h4>Tự kiểm tra</h4><p>Vẽ bản đồ nguồn và điểm thiếu bằng chứng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Hai nhóm nguồn ngoài/nội bộ cùng đi vào bước đối chiếu; bản sao cùng nguồn không được tính độc lập.","altText":"Hai nhóm nguồn ngoài/nội bộ cùng đi vào bước đối chiếu; bản sao cùng nguồn không được tính độc lập."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S03\"><p><strong>03 / Bất định</strong></p><h3>Trình bày khoảng trống và giả định</h3><p>Khi dữ liệu thiếu, công bố khoảng trống, đề xuất cách bổ sung hoặc ước lượng có điều kiện. Dùng nhiều nguồn độc lập để kiểm tra chéo hướng kết luận, nhưng không gọi số nguồn là bằng chứng chắc chắn nếu định nghĩa vẫn khác.</p><aside><h4>Nơi chưa chắc chắn</h4><ul><li>Đã biết · Nguồn và định nghĩa rõ</li><li>Giả định · Cần thử độ nhạy</li><li>Thiếu · Cần thu thập tiếp</li></ul><p>Ba ô tách dữ liệu đã xác nhận, giả định và khoảng trống cần bổ sung.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu giới hạn có thể làm đổi quyết định.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba ô tách dữ liệu đã xác nhận, giả định và khoảng trống cần bổ sung.","altText":"Ba ô tách dữ liệu đã xác nhận, giả định và khoảng trống cần bổ sung."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S04\"><p><strong>04 / Thiết kế</strong></p><h3>Phân rã quyết định thành câu hỏi dữ liệu</h3><p>Viết các phương án có thể chọn, điều kiện để chọn mỗi phương án và rủi ro của quyết định sai. Từ đó suy ra chỉ tiêu cần đo, nguồn và độ mới mong muốn. Không thu thập một trường dữ liệu chỉ vì nó sẵn có nếu không biết nó đổi quyết định nào.</p><aside><h4>Cây quyết định nhỏ</h4><ul><li>Phương án A · Nếu nhu cầu và năng lực đủ</li><li>Phương án B · Nếu chi phí vượt ngưỡng</li><li>Tạm hoãn · Nếu dữ liệu chất lượng thấp</li></ul><p>Ba nhánh quyết định gắn điều kiện dữ liệu và lựa chọn hành động.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu một chỉ tiêu có thể làm đổi phương án.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba nhánh quyết định gắn điều kiện dữ liệu và lựa chọn hành động.","altText":"Ba nhánh quyết định gắn điều kiện dữ liệu và lựa chọn hành động."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S05\"><p><strong>05 / Nguồn độc lập</strong></p><h3>Phối hợp nguồn nhưng không đếm bản sao</h3><p>Nguồn nội bộ cho thấy thực lực; nguồn ngoài cho bối cảnh hoặc chuẩn. Ghi hệ thống nào tạo số, ai xuất báo cáo và phương pháp. Nếu ba trang đều lấy một bảng, chúng là một đường nguồn. Cần ưu tiên nguồn thu thập độc lập cho kiểm tra chéo.</p><aside><h4>Ba hệ thống, hai loại nguồn</h4><ul><li>Ngoài · Bối cảnh ngành</li><li>Nội bộ A · Giao dịch</li><li>Nội bộ B · Vận hành</li><li>Quyết định · Đối chiếu phạm vi</li></ul><p>Sơ đồ ba nguồn đi vào cùng quyết định nhưng giữ rõ nguồn gốc từng hệ thống.</p></aside><section><h4>Tự kiểm tra</h4><p>Vẽ sơ đồ nguồn gốc của ba báo cáo.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Sơ đồ ba nguồn đi vào cùng quyết định nhưng giữ rõ nguồn gốc từng hệ thống.","altText":"Sơ đồ ba nguồn đi vào cùng quyết định nhưng giữ rõ nguồn gốc từng hệ thống."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S06\"><p><strong>06 / Giả định</strong></p><h3>Tính độ nhạy của kết luận</h3><p>Nếu một chỉ số quan trọng chỉ là ước lượng, hãy tính kết luận trong ít nhất hai giả định hợp lý. Đánh dấu giả định nào khiến phương án đổi. Chỉ trình bày một con số đẹp sẽ che rủi ro; một khoảng có điều kiện giúp người ra quyết định biết cần thu thập gì tiếp.</p><aside><h4>Hai kịch bản</h4><ul><li>Thận trọng · Chi phí cao · nhu cầu thấp</li><li>Cơ sở · Theo dữ liệu đã xác nhận</li><li>Điểm đổi · Ngưỡng quyết định</li></ul><p>Ba thẻ so hai kịch bản và chỉ ra điểm mà khuyến nghị có thể thay đổi.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu một giả định làm đổi khuyến nghị.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba thẻ so hai kịch bản và chỉ ra điểm mà khuyến nghị có thể thay đổi.","altText":"Ba thẻ so hai kịch bản và chỉ ra điểm mà khuyến nghị có thể thay đổi."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Lập bản đồ nguồn cho đúng quyết định</h3><p>Kế toán có thể nối sổ cái, hóa đơn và ngân hàng; Marketing nối GA4, quảng cáo và CRM. Với mỗi nguồn, ghi định nghĩa, kỳ, khóa nối và chất lượng sơ bộ. Nếu không có khóa nối tin cậy, không hợp nhất dòng dữ liệu bằng tên gần giống. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu khóa nối nào đã xác minh và khóa nào chưa.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Để lãnh đạo thấy cả điều chưa biết</h3><p>Bản nghiên cứu cần một trang đầu nêu quyết định, kết quả chính, độ chắc chắn, giả định và việc cần làm tiếp. Phụ lục giữ bảng nguồn và phép tính để kiểm tra. Không dùng thuật ngữ “chắc chắn” khi dữ liệu còn thiếu hoặc các nguồn khác định nghĩa.</p><aside><h4>Báo cáo điều hành</h4><ul><li>01 · Quyết định · Nêu lựa chọn</li><li>02 · Căn cứ · Nguồn · bất định</li><li>03 · Điều kiện · Kiểm tra tiếp</li></ul><p>Ba phần của báo cáo điều hành giúp quyết định và giới hạn cùng hiện ra.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một kết luận có mức tin cậy và điều kiện.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba phần của báo cáo điều hành giúp quyết định và giới hạn cùng hiện ra.","altText":"Ba phần của báo cáo điều hành giúp quyết định và giới hạn cùng hiện ra."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Thiết kế bản đồ nguồn cho một quyết định</h3><p>Quyết định mở rộng thị trường cần ít nhất hai phương án và điều kiện chọn. Nguồn thị trường cho bối cảnh, dữ liệu bán hàng cho nhu cầu thực tế, tài chính cho khả năng chi trả. Tam giác hóa đòi hỏi ít nhất ba nguồn gốc độc lập nếu muốn xác lập một khoảng có kiểm chứng; ba báo cáo cùng trích một bảng khảo sát chỉ là một nguồn gốc. Hãy tính kết luận dưới kịch bản cơ sở và thận trọng; chỉ ra giả định nào làm đổi phương án. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Thiết kế bản đồ nguồn cho một quyết định</h3><p>Chuyển quyết định thành chỉ số, nguồn, giả định và phép thử độ nhạy. Thực hiện theo bốn bước: 1) Vẽ hai phương án và một điều kiện tạm hoãn. 2) Nối từng tiêu chí với ít nhất một nguồn nội bộ và một nguồn bên ngoài, kỳ và người sở hữu. 3) Đánh dấu nguồn sao chép, khóa nối chưa xác minh và dữ liệu còn thiếu. 4) Viết hai kịch bản, ngưỡng làm đổi khuyến nghị và mẫu hướng dẫn một đồng nghiệp kiểm tra lại nguồn. Sản phẩm cần tạo: Cây quyết định, bản đồ nguồn và memo nêu giả định/độ bất định.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Vẽ hai phương án và một điều kiện tạm hoãn.</li><li>02 · Nối từng tiêu chí với ít nhất một nguồn nội bộ và một nguồn bên ngoài, kỳ và người sở hữu.</li><li>03 · Đánh dấu nguồn sao chép, khóa nối chưa xác minh và dữ liệu còn thiếu.</li><li>04 · Viết hai kịch bản, ngưỡng làm đổi khuyến nghị và mẫu hướng dẫn một đồng nghiệp kiểm tra lại nguồn.</li></ul><p>Quy trình thực hành thiết kế bản đồ nguồn cho một quyết định có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Quy trình thực hành thiết kế bản đồ nguồn cho một quyết định có sản phẩm kiểm tra được.","altText":"Quy trình thực hành thiết kế bản đồ nguồn cho một quyết định có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-A/M01/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Mỗi dữ liệu thu thập có vai trò trong quyết định. Nguồn độc lập được phân biệt với bản sao. Khuyến nghị nêu điều kiện và việc cần đo tiếp. Lỗi thường gặp: Dùng một con số dự báo duy nhất mà không cho thấy giả định quan trọng. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Mỗi dữ liệu thu thập có vai trò trong quyết định.</li><li>Tiêu chí 2 · Nguồn độc lập được phân biệt với bản sao.</li><li>Tiêu chí 3 · Khuyến nghị nêu điều kiện và việc cần đo tiếp.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Ủy ban châu Âu · DigComp 3.0 · https://joint-research-centre.ec.europa.eu/scientific-activities/key-competences-lifelong-learning/digital-competence-framework-digcomp/digcomp-30_en</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Khi chưa có dữ liệu cho một phần quyết định, cách làm nào minh bạch?","explanation":"Khoảng trống và giả định cần được công bố để người ra quyết định hiểu độ chắc chắn.","options":[{"text":"Tự điền số hợp lý","isCorrect":false},{"text":"Bỏ qua phần đó","isCorrect":false},{"text":"Nêu khoảng trống, giả định và cách kiểm tra tiếp","isCorrect":true}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Thiết kế nghiên cứu cho quyết định đầu tư nên bắt đầu từ đâu?","explanation":"Câu hỏi quyết định định hướng việc cần đo và nguồn cần thu.","options":[{"text":"Thu mọi bảng đang có","isCorrect":false},{"text":"Liệt kê phương án, ngưỡng quyết định, chỉ tiêu và nguồn cần kiểm","isCorrect":true},{"text":"Vẽ biểu đồ trước","isCorrect":false}]},{"text":"Ba trang mạng đều sao chép cùng một bảng. Cách tính nguồn độc lập?","explanation":"Bản sao không tạo thêm bằng chứng độc lập.","options":[{"text":"Ba nguồn","isCorrect":false},{"text":"Một nguồn gốc; cần tìm cách thu thập độc lập nếu muốn kiểm tra chéo","isCorrect":true},{"text":"Không có nguồn nào","isCorrect":false}]},{"text":"Một giả định làm đảo chiều khuyến nghị. Báo cáo nên?","explanation":"Phân tích độ nhạy cho thấy điều kiện của khuyến nghị.","options":[{"text":"Ẩn giả định","isCorrect":false},{"text":"Trình bày hai kịch bản và ngưỡng làm đổi quyết định","isCorrect":true},{"text":"Chỉ giữ kịch bản thuận lợi","isCorrect":false}]}]},{"title":"Đánh giá chất lượng dữ liệu","quizTitle":"Ôn tập · Đánh giá chất lượng dữ liệu","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S01\"><p><strong>01 / Sáu chiều</strong></p><h3>Dữ liệu có đủ tốt cho mục đích?</h3><p>Đo độ đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ và chính xác. Dữ liệu đúng định dạng vẫn có thể sai thực tế; dữ liệu đầy đủ vẫn có thể cũ. Chọn ngưỡng theo rủi ro của quyết định.</p><aside><h4>Sáu chiều chất lượng</h4><ul><li>Đủ · Thiếu trường?</li><li>Duy nhất · Mã trùng?</li><li>Nhất quán · Hai nơi khác?</li><li>Kịp thời · Dữ liệu cũ?</li><li>Hợp lệ · Sai định dạng?</li><li>Chính xác · Sai thực tế?</li></ul><p>Lưới sáu chiều giúp người học phân loại lỗi trước khi tính tỷ lệ.</p></aside><section><h4>Tự kiểm tra</h4><p>Chỉ ra hai chiều quan trọng nhất trong ca này.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Lưới sáu chiều giúp người học phân loại lỗi trước khi tính tỷ lệ.","altText":"Lưới sáu chiều giúp người học phân loại lỗi trước khi tính tỷ lệ."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S02\"><p><strong>02 / Quy tắc</strong></p><h3>Phòng ngừa trước, phát hiện sau</h3><p>Quy tắc ở điểm nhập có thể chặn giá trị ngoài phạm vi; báo cáo ngoại lệ tìm lỗi đã đi vào hệ thống. Mỗi kiểm soát cần công thức đo, ngưỡng, người phụ trách và tần suất kiểm tra. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Hai lớp kiểm soát</h4><ul><li>Phòng ngừa · Ràng buộc lúc nhập</li><li>Phát hiện · Báo cáo ngoại lệ</li><li>Xử lý · Giao người sửa</li></ul><p>Sơ đồ đi từ ngăn lỗi mới tới phát hiện lỗi cũ và giao xử lý.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một quy tắc phòng ngừa và một quy tắc phát hiện.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Sơ đồ đi từ ngăn lỗi mới tới phát hiện lỗi cũ và giao xử lý.","altText":"Sơ đồ đi từ ngăn lỗi mới tới phát hiện lỗi cũ và giao xử lý."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S03\"><p><strong>03 / Ưu tiên</strong></p><h3>Không che giấu dữ liệu yếu</h3><p>Bảng điểm nêu số bản ghi kiểm tra, số lỗi, tỷ lệ và ảnh hưởng tới quyết định. Phân biệt dữ liệu sai với giá trị bất thường cần điều tra. Nếu chất lượng chưa đạt ngưỡng, nêu rõ khuyến nghị tạm thời.</p><aside><h4>Bảng điểm có mẫu số</h4><ul><li>Mẫu kiểm · 100 giao dịch</li><li>Thiếu mã · 2 giao dịch</li><li>Tỷ lệ đủ · 98%</li></ul><p>Ba ô số chỉ rõ mẫu số 100, hai lỗi thiếu mã và tỷ lệ đủ 98%.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi quyết định có thể hoặc chưa thể đưa ra.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba ô số chỉ rõ mẫu số 100, hai lỗi thiếu mã và tỷ lệ đủ 98%.","altText":"Ba ô số chỉ rõ mẫu số 100, hai lỗi thiếu mã và tỷ lệ đủ 98%."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S04\"><p><strong>04 / Công thức</strong></p><h3>Mỗi chiều phải có phép đo</h3><p>Ví dụ độ đầy đủ mã chứng từ bằng số giao dịch có mã chia tổng giao dịch cần mã. Tính duy nhất đo số mã không trùng; tính kịp thời so thời điểm cập nhật với hạn dùng. Ghi rõ mẫu số và ngoại lệ hợp lệ; một tỷ lệ không có mẫu số không đủ để ra quyết định.</p><aside><h4>Công thức độ đầy đủ</h4><ul><li>Có mã · 98 giao dịch</li><li>Cần mã · 100 giao dịch</li><li>Tỷ lệ · 98 / 100 = 98%</li></ul><p>Ba ô số giả lập thể hiện tử số, mẫu số và tỷ lệ đầy đủ mã chứng từ.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết công thức và mẫu số cho một chiều.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba ô số giả lập thể hiện tử số, mẫu số và tỷ lệ đầy đủ mã chứng từ.","altText":"Ba ô số giả lập thể hiện tử số, mẫu số và tỷ lệ đầy đủ mã chứng từ."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S05\"><p><strong>05 / Phân biệt</strong></p><h3>Hợp lệ chưa chắc chính xác</h3><p>Một email đúng cấu trúc có thể thuộc sai khách hàng: hợp lệ về định dạng nhưng sai thực tế. Một giao dịch giá trị lớn có thể là bất thường nhưng chưa chắc sai. Hãy kiểm tra bằng nguồn gốc và quy trình thay vì tự xóa những dòng khác thường.</p><aside><h4>Hai loại kiểm tra</h4><ul><li>Hợp lệ · Đúng định dạng/quy tắc</li><li>Chính xác · Đúng sự thật theo nguồn gốc</li><li>Bất thường · Cần điều tra, chưa phải lỗi</li></ul><p>Ba thẻ phân biệt kiểm tra định dạng, đối chiếu thực tế và tín hiệu bất thường.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu một trường hợp hợp lệ nhưng sai thực tế.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba thẻ phân biệt kiểm tra định dạng, đối chiếu thực tế và tín hiệu bất thường.","altText":"Ba thẻ phân biệt kiểm tra định dạng, đối chiếu thực tế và tín hiệu bất thường."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S06\"><p><strong>06 / Kiểm soát</strong></p><h3>Chặn lỗi mới, tìm lỗi cũ</h3><p>Kiểm soát phòng ngừa ở điểm nhập có thể buộc mã nguồn hoặc kiểm tra định dạng; kiểm soát phát hiện chạy báo cáo thiếu/trùng sau nhập. Với mỗi quy tắc phải có người nhận ngoại lệ, hạn xử lý và bằng chứng đã sửa. Nếu chỉ tạo cảnh báo mà không giao xử lý, chất lượng không cải thiện.</p><aside><h4>Vòng kiểm soát</h4><ul><li>Nhập · Kiểm tra bắt buộc</li><li>Sau nhập · Báo cáo ngoại lệ</li><li>Sửa · Giao người · ghi dấu</li></ul><p>Sơ đồ ba bước cho thấy kiểm soát phòng ngừa và phát hiện cần bước xử lý cuối.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một quy tắc phòng ngừa và một quy tắc phát hiện.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Sơ đồ ba bước cho thấy kiểm soát phòng ngừa và phát hiện cần bước xử lý cuối.","altText":"Sơ đồ ba bước cho thấy kiểm soát phòng ngừa và phát hiện cần bước xử lý cuối."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Ưu tiên lỗi ảnh hưởng quyết định</h3><p>Kế toán ưu tiên mã chứng từ thiếu, mã trùng và khoản chưa khớp ngân hàng; Marketing ưu tiên lead trùng, nguồn thiếu và UTM không hợp lệ. Chọn ngưỡng theo tác động đến báo cáo, không theo một con số chung cho mọi ngành. Ghi rõ khi nào phải tạm dừng kết luận. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Chọn hai lỗi cần xử lý trước và vì sao.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Đọc bảng điểm như một quyết định</h3><p>Báo cáo chất lượng phải ghi bộ dữ liệu, thời điểm đo, mẫu số, số lỗi, tỷ lệ, ngưỡng và người xử lý. Nêu tác động: liệu còn đủ tin cậy để duyệt ngân sách hay chốt báo cáo không? Một bảng toàn màu xanh nhưng không có phép đo là hình trang trí, không phải minh chứng.</p><aside><h4>Quyết định chất lượng</h4><ul><li>Đạt ngưỡng · Dùng có lưu vết</li><li>Chưa đạt · Sửa và đo lại</li><li>Chưa rõ · Nêu giả định</li></ul><p>Ba trạng thái sử dụng dữ liệu dựa trên kết quả đo, không dựa vào màu sắc đơn thuần.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một quyết định dùng/chưa dùng dữ liệu có điều kiện.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba trạng thái sử dụng dữ liệu dựa trên kết quả đo, không dựa vào màu sắc đơn thuần.","altText":"Ba trạng thái sử dụng dữ liệu dựa trên kết quả đo, không dựa vào màu sắc đơn thuần."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Tính bảng điểm chất lượng có mẫu số</h3><p>Giả sử 100 giao dịch phải có mã chứng từ và 98 giao dịch có mã: độ đầy đủ là 98/100 = 98%. Một mã lặp ảnh hưởng tính duy nhất; email đúng cú pháp nhưng thuộc sai người ảnh hưởng tính chính xác. Ghi rõ mẫu số, kỳ đo, ngoại lệ hợp lệ và chủ sở hữu. Không tô ô xanh nếu chưa có phép đo; lỗi chưa giải quyết cần quyết định dùng dữ liệu có điều kiện hay tạm dừng. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Tính bảng điểm chất lượng có mẫu số</h3><p>Đo sáu chiều chất lượng, chọn ngưỡng và giao xử lý ngoại lệ. Thực hiện theo bốn bước: 1) Chọn tập dữ liệu, thời điểm và sáu chiều: đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ, chính xác. 2) Viết tử số, mẫu số/ngưỡng và ít nhất sáu quy tắc kiểm tra có thể áp dụng; phân loại phòng ngừa hoặc phát hiện. 3) Phân loại một bất thường chưa xác minh và một lỗi đã xác nhận. 4) Giao người xử lý, hạn đo lại và quyết định dùng hoặc tạm dừng dữ liệu. Sản phẩm cần tạo: Bảng điểm sáu chiều, ít nhất sáu quy tắc kiểm tra, danh sách ngoại lệ và kế hoạch kiểm soát.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Chọn tập dữ liệu, thời điểm và sáu chiều: đầy đủ, duy nhất, nhất quán, kịp thời, hợp lệ, chính xác.</li><li>02 · Viết tử số, mẫu số/ngưỡng và ít nhất sáu quy tắc kiểm tra có thể áp dụng; phân loại phòng ngừa hoặc phát hiện.</li><li>03 · Phân loại một bất thường chưa xác minh và một lỗi đã xác nhận.</li><li>04 · Giao người xử lý, hạn đo lại và quyết định dùng hoặc tạm dừng dữ liệu.</li></ul><p>Quy trình thực hành tính bảng điểm chất lượng có mẫu số có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Quy trình thực hành tính bảng điểm chất lượng có mẫu số có sản phẩm kiểm tra được.","altText":"Quy trình thực hành tính bảng điểm chất lượng có mẫu số có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-A/M02/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Tỷ lệ có cả tử số, mẫu số và kỳ. Hợp lệ định dạng không bị nhầm với chính xác thực tế. Mỗi ngoại lệ ưu tiên có người xử lý và hạn kiểm tra lại. Lỗi thường gặp: Xóa dòng bất thường để bảng đẹp hơn mà không điều tra và lưu dấu vết. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Tỷ lệ có cả tử số, mẫu số và kỳ.</li><li>Tiêu chí 2 · Hợp lệ định dạng không bị nhầm với chính xác thực tế.</li><li>Tiêu chí 3 · Mỗi ngoại lệ ưu tiên có người xử lý và hạn kiểm tra lại.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Email đúng định dạng nhưng thuộc sai khách hàng vi phạm chiều nào?","explanation":"Định dạng có thể hợp lệ nhưng thông tin không phản ánh đúng thực tế.","options":[{"text":"Tính hợp lệ","isCorrect":false},{"text":"Tính chính xác","isCorrect":true},{"text":"Tính đầy đủ","isCorrect":false}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Có 98/100 giao dịch đủ mã bắt buộc. Độ đầy đủ là?","explanation":"Tử số là 98 dòng đủ mã, mẫu số là 100 dòng cần mã.","options":[{"text":"98%","isCorrect":true},{"text":"2%","isCorrect":false},{"text":"100%","isCorrect":false}]},{"text":"Một email đúng định dạng nhưng gắn sai người. Điều gì chưa đạt?","explanation":"Đúng cấu trúc không bảo đảm đúng đối tượng.","options":[{"text":"Tính hợp lệ định dạng","isCorrect":false},{"text":"Tính chính xác so với thực tế","isCorrect":true},{"text":"Tính kịp thời","isCorrect":false}]},{"text":"Một cảnh báo lỗi được tạo nhưng không ai xử lý. Cần bổ sung gì?","explanation":"Kiểm soát phát hiện chỉ hữu ích khi có luồng xử lý ngoại lệ.","options":[{"text":"Chỉ đổi màu cảnh báo","isCorrect":false},{"text":"Chủ sở hữu, hạn xử lý và dấu vết sửa/đo lại","isCorrect":true},{"text":"Xóa cảnh báo","isCorrect":false}]}]},{"title":"Quản trị dữ liệu và vòng đời thông tin","quizTitle":"Ôn tập · Quản trị dữ liệu và vòng đời thông tin","blocks":[{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S01\"><p><strong>01 / Định nghĩa</strong></p><h3>Một chỉ số cần một cách hiểu</h3><p>Từ điển dữ liệu ghi tên trường, ý nghĩa, kiểu, giá trị hợp lệ, đơn vị, kỳ, nguồn và chủ sở hữu. Khi hai phòng báo số khác nhau, trước hết kiểm tra định nghĩa và nguồn chính thức; không sửa số bằng cách lấy trung bình.</p><aside><h4>Một mục từ điển dữ liệu</h4><ul><li>Tên · Doanh thu thuần</li><li>Định nghĩa · Sau điều chỉnh hợp lệ</li><li>Nguồn · Sổ cái đã chốt</li></ul><p>Phiếu từ điển dữ liệu làm rõ tên, định nghĩa và nguồn chính thức của chỉ số.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết định nghĩa cho một chỉ số hay tranh cãi.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Phiếu từ điển dữ liệu làm rõ tên, định nghĩa và nguồn chính thức của chỉ số.","altText":"Phiếu từ điển dữ liệu làm rõ tên, định nghĩa và nguồn chính thức của chỉ số."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S02\"><p><strong>02 / Trách nhiệm</strong></p><h3>Ai quyết, ai giữ chất lượng?</h3><p>Chủ sở hữu dữ liệu chịu trách nhiệm cuối cùng; người quản lý dữ liệu theo dõi định nghĩa và chất lượng hằng ngày; người sử dụng tuân thủ quy tắc. Ghi quyền phê duyệt thay đổi, nơi lưu nguồn chính thức và đường dẫn truy vết. Tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Ba vai trò</h4><ul><li>01 · Chủ sở hữu · Phê duyệt định nghĩa</li><li>02 · Người quản lý · Theo dõi chất lượng</li><li>03 · Người dùng · Áp dụng đúng quy tắc</li></ul><p>Ba vai trò tách quyền phê duyệt, vận hành chất lượng và sử dụng dữ liệu.</p></aside><section><h4>Tự kiểm tra</h4><p>Gán ba vai trò cho một bộ dữ liệu.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba vai trò tách quyền phê duyệt, vận hành chất lượng và sử dụng dữ liệu.","altText":"Ba vai trò tách quyền phê duyệt, vận hành chất lượng và sử dụng dữ liệu."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S03\"><p><strong>03 / Vòng đời</strong></p><h3>Giữ dữ liệu đúng thời hạn và mục đích</h3><p>Quy trình phải nói rõ tạo, kiểm tra, chia sẻ, lưu, lưu trữ và hủy dữ liệu. Thời hạn giữ cần được đối chiếu quy định và nhu cầu nghiệp vụ tại nơi triển khai; bản demo không tự đặt thời hạn pháp lý.</p><aside><h4>Vòng đời dữ liệu</h4><ul><li>Tạo · Ghi nguồn</li><li>Dùng · Kiểm tra · chia sẻ</li><li>Lưu · Bảo quản theo quy định</li><li>Hủy · Theo chính sách áp dụng</li></ul><p>Trục vòng đời đi từ tạo đến hủy; không ngụ ý một thời hạn lưu giữ chung cho mọi dữ liệu.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết một điểm kiểm soát khi kết thúc vòng đời.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Trục vòng đời đi từ tạo đến hủy; không ngụ ý một thời hạn lưu giữ chung cho mọi dữ liệu.","altText":"Trục vòng đời đi từ tạo đến hủy; không ngụ ý một thời hạn lưu giữ chung cho mọi dữ liệu."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S04\"><p><strong>04 / Từ điển</strong></p><h3>Định nghĩa chỉ số đủ để người khác tính lại</h3><p>Một mục từ điển có tên, định nghĩa, công thức, tử số, mẫu số, đơn vị, kỳ, nguồn chính thức, chủ sở hữu và lịch sử thay đổi. Ví dụ “lead đủ điều kiện” cần điều kiện loại trùng và trạng thái xử lý; “doanh thu” cần cách xử lý hóa đơn hủy.</p><aside><h4>Mục từ điển tối thiểu</h4><ul><li>Tên · Chỉ số nghiệp vụ</li><li>Cách tính · Tử số / mẫu số</li><li>Nguồn · Hệ thống đã chốt</li><li>Chủ sở hữu · Người phê duyệt</li></ul><p>Phiếu từ điển kết nối tên chỉ số với phép tính, nguồn và trách nhiệm.</p></aside><section><h4>Tự kiểm tra</h4><p>Viết định nghĩa và nguồn chính thức cho một chỉ số.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Phiếu từ điển kết nối tên chỉ số với phép tính, nguồn và trách nhiệm.","altText":"Phiếu từ điển kết nối tên chỉ số với phép tính, nguồn và trách nhiệm."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S05\"><p><strong>05 / Chủ sở hữu</strong></p><h3>Phân vai để lỗi có người giải quyết</h3><p>Chủ sở hữu phê duyệt định nghĩa và mức chất lượng; người quản lý dữ liệu theo dõi lỗi và điều phối sửa; người vận hành tạo hoặc cập nhật bản ghi; người dùng báo sai lệch. Ghi ai có quyền đổi định nghĩa vì một thay đổi nhỏ có thể làm đứt chuỗi báo cáo.</p><aside><h4>Chuỗi trách nhiệm</h4><ul><li>01 · Chủ sở hữu · Phê duyệt chuẩn</li><li>02 · Người quản lý · Theo dõi ngoại lệ</li><li>03 · Người vận hành · Sửa có dấu vết</li></ul><p>Ba vai trò tách quyết định chuẩn, theo dõi chất lượng và cập nhật dữ liệu.</p></aside><section><h4>Tự kiểm tra</h4><p>Gán người phê duyệt và người xử lý lỗi khác nhau.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba vai trò tách quyết định chuẩn, theo dõi chất lượng và cập nhật dữ liệu.","altText":"Ba vai trò tách quyết định chuẩn, theo dõi chất lượng và cập nhật dữ liệu."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S06\"><p><strong>06 / Thay đổi</strong></p><h3>Phiên bản hóa định nghĩa, không sửa âm thầm</h3><p>Khi đổi cách tính, ghi đề xuất, tác động tới báo cáo cũ, người duyệt, ngày hiệu lực và phiên bản mới. Giữ khả năng giải thích vì sao số tháng trước khác sau thay đổi. Không ghi đè từ điển mà không có lịch sử; người đọc có thể hiểu nhầm sự thay đổi là tăng trưởng thật.</p><aside><h4>Thay đổi có kiểm soát</h4><ul><li>v1 · Định nghĩa cũ</li><li>Duyệt · Tác động và người duyệt</li><li>v2 · Ngày hiệu lực rõ</li></ul><p>Trục phiên bản cho thấy định nghĩa mới cần phê duyệt và ngày áp dụng.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu ba thông tin bắt buộc trong nhật ký thay đổi.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Trục phiên bản cho thấy định nghĩa mới cần phê duyệt và ngày áp dụng.","altText":"Trục phiên bản cho thấy định nghĩa mới cần phê duyệt và ngày áp dụng."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S07\"><p><strong>07 / Ca theo vị trí</strong></p><h3>Thiết kế chuẩn cho bộ dữ liệu đang dùng</h3><p>Với Kế toán, xác định nguồn chính thức của doanh thu, trạng thái hóa đơn và người xử lý đối chiếu; với Marketing, xác định lead đủ điều kiện, nguồn chiến dịch và người quản trị UTM. Quyền truy cập phải phù hợp mức nhạy cảm, nhất là thông tin khách hàng và tài chính. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện của Vị trí khác</h4><ul><li>Nhiệm vụ · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li><li>Nguồn · Ghi tài liệu gốc và kỳ dữ liệu</li><li>Sản phẩm · Có thể kiểm tra lại</li></ul><p>Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.</p></aside><section><h4>Tự kiểm tra</h4><p>Ghi một quy tắc truy cập và một quy tắc chất lượng.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật.","altText":"Bảng dữ kiện giả lập của đúng vị trí được dùng để luyện tập, không phải số liệu doanh nghiệp thật."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S08\"><p><strong>08 / Tự kiểm</strong></p><h3>Kiểm tra toàn vòng đời</h3><p>Mô tả cách dữ liệu được tạo, xác minh, chia sẻ, lưu, lưu trữ và hủy theo chính sách áp dụng. Không đặt một thời hạn lưu chung trong bài học vì yêu cầu pháp lý và nghiệp vụ có thể khác. Bản cuối phải cho thấy cách duy trì chất lượng sau khi dự án phân tích kết thúc.</p><aside><h4>Vòng đời có điểm kiểm soát</h4><ul><li>Tạo · Mã · nguồn</li><li>Dùng · Quyền · chất lượng</li><li>Lưu · Theo chính sách</li><li>Hủy · Có phê duyệt</li></ul><p>Trục vòng đời chỉ vị trí cần kiểm soát, không tự quy định số năm lưu giữ.</p></aside><section><h4>Tự kiểm tra</h4><p>Nêu điểm kiểm soát ở lúc tạo và lúc kết thúc vòng đời.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Trục vòng đời chỉ vị trí cần kiểm soát, không tự quy định số năm lưu giữ.","altText":"Trục vòng đời chỉ vị trí cần kiểm soát, không tự quy định số năm lưu giữ."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S09\"><p><strong>09 / Làm mẫu</strong></p><h3>Làm mẫu · Tạo từ điển chỉ số và kiểm soát thay đổi</h3><p>“Lead đủ điều kiện” không thể chỉ là tên cột; cần điều kiện đủ chuẩn, cách loại trùng, trạng thái, kỳ, nguồn chính thức và chủ sở hữu. Tương tự, “doanh thu” phải nêu xử lý hóa đơn hủy/điều chỉnh. Nếu thay điều kiện, ghi đề xuất, tác động tới số cũ, người duyệt, ngày hiệu lực và phiên bản. Truy cập dữ liệu nhạy cảm theo quyền phù hợp, không tự đặt một thời hạn lưu chung cho mọi tổ chức. Trong tình huống Vị trí khác: Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</p><aside><h4>Dữ kiện để làm mẫu</h4><ul><li>Nguồn 1 · Áp dụng vào một quyết định thực tế của vị trí.</li><li>Nguồn 2 · Hãy áp dụng với một nguồn dữ liệu phù hợp vị trí và ghi lại cách kiểm tra.</li></ul><p>Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu nơi ví dụ nêu nguồn, thao tác và giới hạn.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun.","altText":"Dữ kiện giả lập của Vị trí khác dùng để minh họa cách xử lý trong mô đun."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S10\"><p><strong>10 / Thực hành</strong></p><h3>Tự làm · Tạo từ điển chỉ số và kiểm soát thay đổi</h3><p>Định nghĩa một chỉ số để phòng ban khác tính lại được và biết ai chịu trách nhiệm. Thực hiện theo bốn bước: 1) Chọn một chỉ số có tranh cãi giữa hai phòng ban. 2) Tạo từ điển ít nhất mười trường, mỗi trường có định nghĩa, kiểu/giá trị hợp lệ, nguồn, mức nhạy cảm và chủ sở hữu. 3) Gán chủ sở hữu, người quản lý chất lượng và người vận hành; xác định nguồn chính thức. 4) Mô phỏng thay đổi v1→v2 và lập lịch lưu/hủy cho ba loại dữ liệu theo chính sách áp dụng. Sản phẩm cần tạo: Từ điển tối thiểu 10 trường, ma trận ba vai trò, định nghĩa chỉ số thống nhất và lịch lưu/hủy cho ba loại dữ liệu.</p><aside><h4>Bốn bước thực hành</h4><ul><li>01 · Chọn một chỉ số có tranh cãi giữa hai phòng ban.</li><li>02 · Tạo từ điển ít nhất mười trường, mỗi trường có định nghĩa, kiểu/giá trị hợp lệ, nguồn, mức nhạy cảm và chủ sở hữu.</li><li>03 · Gán chủ sở hữu, người quản lý chất lượng và người vận hành; xác định nguồn chính thức.</li><li>04 · Mô phỏng thay đổi v1→v2 và lập lịch lưu/hủy cho ba loại dữ liệu theo chính sách áp dụng.</li></ul><p>Quy trình thực hành tạo từ điển chỉ số và kiểm soát thay đổi có sản phẩm kiểm tra được.</p></aside><section><h4>Tự kiểm tra</h4><p>Tạo sản phẩm trên dữ liệu mẫu hoặc dữ liệu công việc đã được phép sử dụng.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Quy trình thực hành tạo từ điển chỉ số và kiểm soát thay đổi có sản phẩm kiểm tra được.","altText":"Quy trình thực hành tạo từ điển chỉ số và kiểm soát thay đổi có sản phẩm kiểm tra được."},{"bodyHtml":"<article data-slide-code=\"M1-A/M03/S11\"><p><strong>11 / Tự chấm</strong></p><h3>So sản phẩm với tiêu chí</h3><p>Sản phẩm cần đạt ba dấu hiệu: Một người ngoài nhóm có thể tính lại chỉ số từ định nghĩa. Nguồn chính thức và quyền truy cập rõ ràng. Thay đổi định nghĩa không bị nhầm với tăng/giảm thực tế. Lỗi thường gặp: Sửa công thức trong dashboard nhưng không cập nhật từ điển và lịch sử. Nếu thiếu nguồn hoặc giả định chưa rõ, bổ sung trước khi chuyển sang quiz. Bài thực hành này giúp chuẩn bị minh chứng cho bài cuối khóa; quiz vẫn kiểm tra hiểu biết cá nhân.</p><aside><h4>Phiếu tự kiểm</h4><ul><li>Tiêu chí 1 · Một người ngoài nhóm có thể tính lại chỉ số từ định nghĩa.</li><li>Tiêu chí 2 · Nguồn chính thức và quyền truy cập rõ ràng.</li><li>Tiêu chí 3 · Thay đổi định nghĩa không bị nhầm với tăng/giảm thực tế.</li></ul><p>Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.</p></aside><section><h4>Tự kiểm tra</h4><p>Đánh dấu tiêu chí chưa đạt và sửa một điểm cụ thể.</p></section><footer><strong>Nguồn tham khảo:</strong> Chính phủ Anh · Khung chất lượng dữ liệu · https://www.gov.uk/government/publications/the-government-data-quality-framework/the-government-data-quality-framework</footer></article>","caption":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa.","altText":"Ba tiêu chí kiểm tra kết quả thực hành trước khi nộp bài cuối khóa."}],"questions":[{"text":"Hai phòng ban báo một chỉ số khác nhau vì định nghĩa khác. Cần làm gì trước?","explanation":"Quản trị giải quyết khác biệt định nghĩa trước khi xử lý phép tính.","options":[{"text":"Lấy trung bình hai số","isCorrect":false},{"text":"Chọn số cao hơn","isCorrect":false},{"text":"Thống nhất định nghĩa và nguồn chính thức trong từ điển dữ liệu","isCorrect":true}]},{"text":"Kết quả công việc nào kiểm tra được?","explanation":"Nguồn và cách làm phải đi cùng kết luận.","options":[{"text":"Một kết luận không ghi nguồn","isCorrect":false},{"text":"Nguồn, cách làm và kết luận có giới hạn","isCorrect":true},{"text":"Chỉ một ảnh chụp","isCorrect":false}]},{"text":"Mục từ điển cho chỉ số cần tối thiểu gì?","explanation":"Người khác phải tính lại được và biết ai chịu trách nhiệm.","options":[{"text":"Tên và màu biểu đồ","isCorrect":false},{"text":"Định nghĩa, công thức, kỳ, nguồn chính thức, chủ sở hữu","isCorrect":true},{"text":"Chỉ tên người nhập dữ liệu","isCorrect":false}]},{"text":"Đổi công thức tính chỉ số. Hành động nào có kiểm soát?","explanation":"Lịch sử thay đổi giúp phân biệt thay đổi định nghĩa với thay đổi thực tế.","options":[{"text":"Ghi đè mà không thông báo","isCorrect":false},{"text":"Ghi tác động, người duyệt, ngày hiệu lực và phiên bản mới","isCorrect":true},{"text":"Chỉ sửa ảnh biểu đồ","isCorrect":false}]},{"text":"Dữ liệu hết thời hạn sử dụng. Cách xử lý đúng?","explanation":"Vòng đời dữ liệu cần tuân thủ chính sách cụ thể của tổ chức và quy định áp dụng.","options":[{"text":"Giữ mãi mọi bản sao","isCorrect":false},{"text":"Theo chính sách áp dụng, xác định người phê duyệt và lưu dấu vết xử lý","isCorrect":true},{"text":"Xóa tùy ý không ghi nhận","isCorrect":false}]}]}]}]}$domain1_platform_v2$::jsonb);

CREATE TEMP TABLE pulse_platform_courses AS
SELECT v.id AS version_id, v.version_no, cc.id AS catalog_course_id, pc.id AS course_id,
       pc.code, source.value AS doc
FROM pulse_platform_payload payload
CROSS JOIN LATERAL jsonb_array_elements(payload.data->'courses') source(value)
JOIN platform_courses pc ON pc.code = source.value->>'code'
JOIN platform_catalog_versions v ON v.status = 'DRAFT'
JOIN platform_catalog_courses cc ON cc.version_id = v.id AND cc.course_id = pc.id;

DO $$ BEGIN
  IF (SELECT count(*) FROM platform_catalog_versions WHERE status='DRAFT') <> 1
     OR (SELECT count(*) FROM pulse_platform_courses) <> 3
     OR (SELECT count(DISTINCT version_id) FROM pulse_platform_courses) <> 1
  THEN RAISE EXCEPTION 'Cần đúng một catalog DRAFT chứa đủ A1-F, A1-I, A1-A; dừng import.'; END IF;
END $$;

DELETE FROM platform_question_options option_row
USING platform_module_questions question_row, platform_course_modules module_row, pulse_platform_courses selected_course
WHERE option_row.question_id=question_row.id AND question_row.module_id=module_row.id AND module_row.catalog_course_id=selected_course.catalog_course_id;
DELETE FROM platform_module_questions question_row
USING platform_course_modules module_row, pulse_platform_courses selected_course
WHERE question_row.module_id=module_row.id AND module_row.catalog_course_id=selected_course.catalog_course_id;
DELETE FROM platform_slide_items slide_item
USING platform_module_blocks block_row, platform_course_modules module_row, pulse_platform_courses selected_course
WHERE slide_item.block_id=block_row.id AND block_row.module_id=module_row.id AND module_row.catalog_course_id=selected_course.catalog_course_id;
DELETE FROM platform_module_blocks block_row
USING platform_course_modules module_row, pulse_platform_courses selected_course
WHERE block_row.module_id=module_row.id AND module_row.catalog_course_id=selected_course.catalog_course_id;
DELETE FROM platform_course_modules module_row
USING pulse_platform_courses selected_course
WHERE module_row.catalog_course_id=selected_course.catalog_course_id;

UPDATE platform_catalog_courses catalog_course
SET title=selected_course.doc->>'title', outcome=selected_course.doc->>'outcome',
    final_title=selected_course.doc->'final'->>'title', final_prompt=selected_course.doc->'final'->>'promptHtml',
    final_criteria=selected_course.doc->'final'->'criteria', change_kind='EDITED', updated_at=now()
FROM pulse_platform_courses selected_course
WHERE catalog_course.id=selected_course.catalog_course_id;

CREATE TEMP TABLE pulse_platform_modules AS
SELECT selected_course.*, module_doc.ordinality::int AS module_no, module_doc.value AS module_doc,
       md5('pulse-platform-domain1-v2:module:' || selected_course.catalog_course_id::text || ':' || module_doc.ordinality::text)::uuid AS module_id
FROM pulse_platform_courses selected_course
CROSS JOIN LATERAL jsonb_array_elements(selected_course.doc->'modules') WITH ORDINALITY module_doc(value, ordinality);

INSERT INTO platform_course_modules (id, catalog_course_id, sort_order, title, quiz_title, created_at, updated_at)
SELECT module_id, catalog_course_id, module_no, module_doc->>'title', module_doc->>'quizTitle', now(), now()
FROM pulse_platform_modules;

CREATE TEMP TABLE pulse_platform_blocks AS
SELECT module_row.*, block_doc.ordinality::int AS block_no, block_doc.value AS block_doc,
       md5('pulse-platform-domain1-v2:block:' || module_row.module_id::text || ':' || block_doc.ordinality::text)::uuid AS block_id
FROM pulse_platform_modules module_row
CROSS JOIN LATERAL jsonb_array_elements(module_row.module_doc->'blocks') WITH ORDINALITY block_doc(value, ordinality);

INSERT INTO platform_module_blocks (id, module_id, sort_order, block_type, body_html, asset_id, caption, alt_text, created_at, updated_at)
SELECT block_id, module_id, block_no, 'TEXT', block_doc->>'bodyHtml', NULL, block_doc->>'caption', block_doc->>'altText', now(), now()
FROM pulse_platform_blocks;

CREATE TEMP TABLE pulse_platform_questions AS
SELECT module_row.*, question_doc.ordinality::int AS question_no, question_doc.value AS question_doc,
       md5('pulse-platform-domain1-v2:question:' || module_row.module_id::text || ':' || question_doc.ordinality::text)::uuid AS question_id
FROM pulse_platform_modules module_row
CROSS JOIN LATERAL jsonb_array_elements(module_row.module_doc->'questions') WITH ORDINALITY question_doc(value, ordinality);

INSERT INTO platform_module_questions (id, module_id, sort_order, question_text, explanation, block_id, created_at, updated_at)
SELECT question_id, module_id, question_no, question_doc->>'text', question_doc->>'explanation', NULL, now(), now()
FROM pulse_platform_questions;

INSERT INTO platform_question_options (id, question_id, sort_order, option_text, is_correct, created_at, updated_at)
SELECT md5('pulse-platform-domain1-v2:option:' || question_row.question_id::text || ':' || option_doc.ordinality::text)::uuid,
       question_row.question_id, option_doc.ordinality::int, option_doc.value->>'text',
       (option_doc.value->>'isCorrect')::boolean, now(), now()
FROM pulse_platform_questions question_row
CROSS JOIN LATERAL jsonb_array_elements(question_row.question_doc->'options') WITH ORDINALITY option_doc(value, ordinality);

DO $$ BEGIN
  IF (SELECT count(*) FROM pulse_platform_modules) <> 9 THEN
    RAISE EXCEPTION 'Platform Draft v2: cần 9 mô đun, hiện có %.', (SELECT count(*) FROM pulse_platform_modules);
  END IF;
  IF (SELECT count(*) FROM pulse_platform_blocks) <> 99 THEN
    RAISE EXCEPTION 'Platform Draft v2: cần 99 khối, hiện có %.', (SELECT count(*) FROM pulse_platform_blocks);
  END IF;
  IF (SELECT count(*) FROM pulse_platform_questions) <> 45 THEN
    RAISE EXCEPTION 'Platform Draft v2: cần 45 câu hỏi, hiện có %.', (SELECT count(*) FROM pulse_platform_questions);
  END IF;
  IF EXISTS (
    SELECT 1 FROM pulse_platform_courses selected_course
    WHERE (SELECT count(*) FROM platform_course_modules m WHERE m.catalog_course_id=selected_course.catalog_course_id) <> 3
       OR (SELECT count(*) FROM platform_module_blocks b JOIN platform_course_modules m ON m.id=b.module_id WHERE m.catalog_course_id=selected_course.catalog_course_id) <> 33
       OR (SELECT count(*) FROM platform_module_questions q JOIN platform_course_modules m ON m.id=q.module_id WHERE m.catalog_course_id=selected_course.catalog_course_id) <> 15
       OR (SELECT count(*) FROM platform_question_options o JOIN platform_module_questions q ON q.id=o.question_id JOIN platform_course_modules m ON m.id=q.module_id WHERE m.catalog_course_id=selected_course.catalog_course_id AND o.is_correct) <> 15
       OR (SELECT change_kind FROM platform_catalog_courses c WHERE c.id=selected_course.catalog_course_id) <> 'EDITED')
  THEN RAISE EXCEPTION 'Platform Draft v2: số liệu từng khóa hoặc trạng thái EDITED không hợp lệ.'; END IF;
END $$;

SELECT version_no, code,
       (SELECT change_kind FROM platform_catalog_courses c WHERE c.id=selected_course.catalog_course_id) change_kind,
       (SELECT count(*) FROM platform_course_modules m WHERE m.catalog_course_id=selected_course.catalog_course_id) modules,
       (SELECT count(*) FROM platform_module_blocks b JOIN platform_course_modules m ON m.id=b.module_id WHERE m.catalog_course_id=selected_course.catalog_course_id) blocks,
       (SELECT count(*) FROM platform_module_questions q JOIN platform_course_modules m ON m.id=q.module_id WHERE m.catalog_course_id=selected_course.catalog_course_id) questions
FROM pulse_platform_courses selected_course ORDER BY code;
ROLLBACK;
